import json
import os

class DataStore:
    def __init__(self, path, fail_on_missing=False):
        self.path = path
        self.fail_on_missing = fail_on_missing
        self.data = None
        self.file = None

    def _load_from_file(self):
        if self.path.endswith('.json'):
            self.file = open(self.path, 'r')
            self.load_json_file()
        else:
            raise ValueError(f"Unsupported file type: {self.path}")

    def load_file(self):
        if not self.path:
            return None
        if os.path.exists(self.path):
            self._load_from_file()
        elif self.fail_on_missing:
            raise FileNotFoundError(f"Input file '{self.path}' not found")
        return self

    def _load_json_file(self):
        with self.file:
            self.data = json.load(self.file)

    def load_json(self, data):
        self.data = data

    def as_json(self):
        return json.dumps(self.data, indent=4)

    def __iter__(self):
        if self.data is None:
            self._load_from_file()
        if self.data is None:
            return
        yield from self.data.items()

    def __next__(self):
        try:
            return next(self.data.items())
        except AttributeError:
            return self.as_json()
