import psutil
import os
import time
import math
import platform
import subprocess

def terminate_process(pid, initial_sleep=0.5, max_sleep=5, sleep_factor=2):
    if pid <= 0:
        return -1

    failed_attempts = 0
    current_sleep = initial_sleep

    while True:
        try:
            if not psutil.pid_exists(pid):
                return 0

            process = psutil.Process(pid)
            if not process.is_running():
                return 0

            if psutil.access_permissions(process) & psutil.ACCESS_PERMS:
                process.terminate()
                return 0
            else:
                if platform.system() == 'Windows':
                    try:
                        subprocess.check_call(['taskkill', '/PID', str(pid), '/F', '/T'], shell=True)
                        return 0
                    except subprocess.CalledProcessError:
                        pass
                else:
                    try:
                        os.kill(pid, 9)
                        return 0
                    except OSError:
                        pass

            failed_attempts += 1
            time.sleep(current_sleep)

            if failed_attempts >= 10:
                break

            current_sleep *= sleep_factor
            if current_sleep > max_sleep:
                current_sleep = max_sleep
        except Exception as e:
            return -1

    return -1
