import ipmitool
import getpass
import sys
import sqlite3

def get_credentials(db_name):
    """Retrieve username and password from the database"""
    try:
        conn = sqlite3.connect(db_name)
        cursor = conn.cursor()
        cursor.execute("SELECT * FROM credentials")
        return cursor.fetchone()
    except sqlite3.Error as e:
        print(f"Error retrieving credentials: {e}")
        sys.exit(1)
    finally:
        if conn:
            conn.close()

def power_remote_device(ip, username, password, power_state):
    """Perform power operation on the remote device"""
    ipmi = ipmitool.IPMI(ip, username, password)
    if power_state == "on":
        command = f"power {power_state}"
    elif power_state == "off":
        command = f"power {power_state} force"
    else:
        print("Invalid power state. Please use 'on' or 'off'.")
        sys.exit(1)
    result = ipmi.command(command)
    if "OK" in result:
        print(f"Command executed successfully: {command}")
    else:
        print(f"Failed to execute command: {command}\nResult: {result}")

def main():
    db_name = "credentials.db"
    credentials = get_credentials(db_name)
    if credentials:
        ip = input("Enter IP address: ")
        power_state = input("Enter power state (on/off): ")
        username = credentials[1]
        password = getpass.getpass(prompt="Enter password: ", stream=None)
        power_remote_device(ip, username, password, power_state)

if __name__ == "__main__":
    main()
