def create_zip_file(path, filename):
    """Creates a zip file from the given path."""
    with zipfile.ZipFile(f'{filename}.zip', 'w') as zip_file:
        for root, dirs, files in os.walk(path):
            for file in files:
                zip_file.write(os.path.join(root, file), os.path.relpath(os.path.join(root, file), path))

