import os
import tarfile

def extract_tarball(tarball_path, extract_path):
    """
    Extracts a tarball file to a specified directory.

    Args:
    tarball_path (str): Path to the tarball file.
    extract_path (str): Path to the directory where the tarball will be extracted.
    """

    # Check if the tarball file exists
    if not os.path.exists(tarball_path):
        raise FileNotFoundError(f"The tarball file does not exist at: {tarball_path}")

    # Check if the extraction directory exists, if not create it
    if not os.path.exists(extract_path):
        os.makedirs(extract_path)

    # Check if the tarball is a tar file
    if not tarball_path.endswith('.tar') or not tarball_path.endswith('.tgz') or not tarball_path.endswith('.tar.gz'):
        raise ValueError(f"Unsupported tarball file type: {tarball_path}")

    # Open the tarball in read mode
    with tarfile.open(tarball_path, 'r:gz' if tarball_path.endswith('.tgz') or tarball_path.endswith('.tar.gz') else 'r') as tar:
        # Extract the tarball to the specified directory
        tar.extractall(path=extract_path)

    # Ensure the extracted files and directories are properly permissions-ed
    for root, dirs, files in os.walk(extract_path):
        for file in files:
            try:
                os.chmod(os.path.join(root, file), 0o644)
            except OSError as e:
                print(f"Error setting permissions for file: {file}")
        for dir in dirs:
            try:
                os.chmod(os.path.join(root, dir), 0o755)
            except OSError as e:
                print(f"Error setting permissions for directory: {dir}")
