class Command(ABC):
    @abstractmethod
    def execute(self):
        pass

class CommandError(Exception):
    pass

class Save(Command):
    def __init__(self, path):
        self.path = path

    def execute(self):
        try:
            with open(self.path, 'w') as file:
                file.write('Test string')
        except Exception as e:
