import distutils.core
from distutils import util

def generate_readme(file_path, replacements, output_path):
    """
    Generate a README file by filling in placeholders in the template.

    Args:
        file_path (str): Path to the template README file.
        replacements (dict): Dictionary where keys are placeholders and values are lists
            of values to replace the placeholders.
        output_path (str): Path to write the generated README file.
    """

    try:
        with open(file_path, 'r') as template_file, open(output_path, 'w') as output_file:
            for line in template_file:
                for key, value in replacements.items():
                    if f'{{{key}}}' in line:
                        # When inserting a list into the README text, convert it to a comma-separated string
                        if isinstance(value, list) and ',' in value[0]:
                            line = line.replace(f'{{{key}}}', ', '.join(value), 1)
                        else:
                            line = line.replace(f'{{{key}}}', ', '.join(map(str, value)), 1)
                output_file.write(line)
            output_file.write('[Modules]\n')
            for module in util.convert_path(replacements['modules']):
                if module!= 'builtins':
                    output_file.write(f'* {module}\n')
    except FileNotFoundError:
        print(f"Error: {file_path} not found")
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == '__main__':
