import pandas as pd

class CSVTransformer:
    def __init__(self, csv_file, transformations={}):
        self.csv_file = csv_file
        self.transformations = transformations
        self.column_mapping = {}

    def set_transformations(self, transformations):
        self.transformations = transformations

    def apply_transformations(self):
        try:
            self.data = pd.read_csv(self.csv_file)
            self.apply_type_transformations()
            self.apply_logical_transformations()
        except FileNotFoundError:
            print("File not found.")

    def apply_type_transformations(self):
        for column, transform_function in self.transformations.items():
            if column in self.data.columns and transform_function['type'] in ['int', 'float','str']:
                if transform_function['type'] == 'int':
                    self.data[column] = pd.to_numeric(self.data[column], errors='coerce')
                elif transform_function['type'] == 'float':
                    self.data[column] = pd.to_numeric(self.data[column], errors='coerce').astype(float)
                elif transform_function['type'] =='str':
                    self.data[column] = self.data[column].astype(str)
                self.column_mapping[column] = transform_function['type']

    def apply_logical_transformations(self):
        for column, transform_function in self.transformations.items():
            if column in self.data.columns and transform_function['type'] in ['round', 'fillna']:
                if 'values' in transform_function and 'target' in transform_function:
                    if transform_function['type'] == 'round':
                        self.data[column] = self.data[column].round(transform_function['values'])
                    elif transform_function['type'] == 'fillna':
                        self.data[column] = self.data[column].fillna(transform_function['values'])
                self.column_mapping[column] = transform_function


    def save_transformed_data(self, output_file):
        self.data.to_csv(output_file, index=False)

transformations = {
    'age': {'type': 'int'},
    'price': {'type': 'float', 'round': 2},
    'name': {'type':'str'}
}

