import os
import numpy as np
from multiprocessing import Process
import socket
import pickle
import gzip
import hashlib

class Block:
    def __init__(self, size, data):
        self.size = size
        self.data = data
        self.hash = hashlib.md5(data).hexdigest()

    def compress(self):
        return gzip.compress(self.data)

    @classmethod
    def decompress(cls, compressed_data):
        return cls(np.array(compressed_data).nbytes, gzip.decompress(compressed_data))

class Node:
    def __init__(self, hostname):
        self.hostname = hostname
        self.block_file = f"{hostname}_blocks.pkl"
        self.blocks = {}

    def store(self, block):
        with open(self.block_file, 'rb') as f:
            loaded_blocks = pickle.load(f)
        loaded_blocks[block.hash] = block
        with open(self.block_file, 'wb') as f:
            pickle.dump(loaded_blocks, f)

    def get_block(self, hash):
        with open(self.block_file, 'rb') as f:
            blocks = pickle.load(f)
        return blocks.get(hash)

    def start_server(self):
        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.bind(('localhost', 12345))
        self.server_socket.listen()

    def serve(self):
        while True:
            conn, addr = self.server_socket.accept()
            request = conn.recv(1024).decode()
            if request.startswith('get'):
                hash = request[4:]
                block = self.get_block(hash)
                if block:
                    compressed_data = np.frombuffer(block.compress(), dtype='b')
                    conn.sendall(compressed_data.tobytes())
                    conn.close()
                else:
                    conn.sendall(b'NOT FOUND')
                    conn.close()
            else:
                conn.sendall(b'NOT VALID')
                conn.close()

def worker(hostname):
    node = Node(hostname)
    node.start_server()
    node.serve()

if __name__ == '__main__':
    num_nodes = 4
    nodes = []
    for i in range(num_nodes):
        hostname = f'node_{i}'
        node = Process(target=worker, args=(hostname,))
        node.start()
        nodes.append(node)
    for node in nodes:
        node.join()
```

This code creates a basic distributed filesystem implementation, in which nodes store compressed blocks of data and return them on request. Each node has a file to store the blocks, and sockets are used for communication between nodes. 

Please note that this is a simplified example and doesn't cover all the complexities of a real-world distributed filesystem. The code does not handle failure scenarios (e.g., network failures, node crashes), data consistency, or concurrency. 

In a production-ready distributed filesystem, you would need to consider these aspects and design the system for scalability, reliability, and performance. 

In this example, we're just demonstrating the core concept and the structure of such a system.

