import psutil

class DiskUsageAnalyzer:
    def __init__(self, path='.'):
        self.path = path

    def get_disk_usage(self):
        try:
            usage = psutil.disk_usage(self.path)
        except psutil.Error as e:
            print(f"Error getting disk usage: {e}")
            return None
        return usage

    def get_top_large_files(self, max_files=100):
        files = []
        for root, dirs, filenames in os.walk(self.path):
            for filename in filenames:
                filepath = os.path.join(root, filename)
                try:
                    file_size = os.path.getsize(filepath)
                except Exception as e:
                    print(f"Error getting file size: {e}")
                    continue
                files.append((filepath, file_size))
        files.sort(key=lambda x: x[1], reverse=True)
        return files[:max_files]

    def report_large_files(self, max_files=100):
        usage = self.get_disk_usage()
        if usage is None:
            return
        largest_files = self.get_top_large_files(max_files)
        print(f"Disk usage: {usage.percent}%")
        print(f"Top {max_files} large files:")
        for file, size in largest_files:
            print(f"{file}: {size} bytes")

if __name__ == "__main__":
    analyzer = DiskUsageAnalyzer('/path/to/your/directory')
    analyzer.report_large_files()
