import tarfile
import shutil
import os

def extract_and_organize(tar_path):
    try:
        tar = tarfile.open(tar_path, 'r')
        for member in tar.getmembers():
            if member.name.startswith('src/'):
                if not os.path.exists('lib'):
                    os.makedirs('lib')
                dest_path = f'lib/{member.name.replace("src/", "")}'
                if os.path.exists(dest_path):
                    raise FileExistsError(f"Destination path {dest_path} already exists.")
                shutil.move(member, dest_path)
            elif member.name.startswith('tests/'):
                dest_path = f'tests/{member.name}'
                if os.path.exists(dest_path):
                    raise FileExistsError(f"Destination path {dest_path} already exists.")
                shutil.move(member, dest_path)
        tar.close()
    except tarfile.TarError as e:
        print(f"Failed to read tarball: {e}")
    except FileNotFoundError:
        print("Error: tarball file not found.")
    except FileExistsError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

def package_and_compress(src_path, tar_path):
    try:
        with tarfile.open(tar_path, 'w:gz') as tar:
            tar.add(src_path, arcname='src/')
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

def main():
    src_path ='src'
    tar_path = 'build.tar.gz'
    if os.path.exists(tar_path):
        extract_and_organize(tar_path)
    else:
        package_and_compress(src_path, tar_path)
        extract_and_organize(tar_path)

if __name__ == "__main__":
    main()
