import os
import tempfile
import subprocess

class DiskImageData:
    def __init__(self, image_path):
        self.image_path = image_path
        self.mount_point = None

    def mount_disk_image(self):
        if not self.mount_point:
            temp_dir = tempfile.mkdtemp()
            mount_command = f"sudo mount -o loop,ro {self.image_path} {temp_dir}"
            self.subprocess(mount_command)
            self.mount_point = temp_dir

    def unmount_disk_image(self):
        if self.mount_point:
            unmount_command = f"sudo umount {self.mount_point}"
            self.subprocess(unmount_command)
            self.mount_point = None

    def extract_files(self, output_dir):
        if not self.mount_point:
            self.mount_disk_image()
        if not os.path.isdir(output_dir):
            os.makedirs(output_dir)
        copy_command = f"rsync -avz {self.mount_point}/ {output_dir}"
        self.subprocess(copy_command)

    def subprocess(self, command):
        result = subprocess.run(command, shell=True, capture_output=True, check=False)
        if result.returncode!= 0:
            raise Exception(f"Error running command: {command}")

class DiskImageHandler:
    def __init__(self, image_path):
        self.image_data = DiskImageData(image_path)

    def mount(self):
        self.image_data.mount_disk_image()

    def unmount(self):
        self.image_data.unmount_disk_image()

    def extract(self, output_dir):
