from pathlib import Path
import tempfile

class DiskImageManager:
    def __init__(self, image_path):
        self.image_path = image_path

    def mount(self, mount_point, password=None):
        """
        Mount the disk image as a filesystem.

        :param mount_point: The path to mount the image.
        :param password: The password to use for encrypted images.
        """
        if not os.path.exists(self.image_path):
            raise FileNotFoundError(f"Image path '{self.image_path}' does not exist.")

        if not os.path.exists(mount_point):
            os.makedirs(mount_point)

        try:
            output = subprocess.check_output([
                'qemu-img', 'convert', '-O', 'raw', self.image_path, '-o', f'format=qcow2', f'{mount_point}/image.qcow2'
            ])
        except FileNotFoundError:
            raise Exception("qemu-img not found. Please install it.")

        try:
            output = subprocess.check_output([
                'kpartx', '-a', f'{mount_point}/image.qcow2'
            ])
        except FileNotFoundError:
            raise Exception("kpartx not found. Please install it.")

        device = f'/dev/mapper/loop0'
        if device not in os.listdir('/dev/mapper'):
            raise Exception(f"Failed to create device '{device}'")

        for partition in mount_point:
            try:
                output = subprocess.check_output([
                   'mount', f'{device}p1', partition
                ])
            except subprocess.CalledProcessError as e:
                if not password:
                    raise Exception("Password is required to mount encrypted partitions.")
                output = subprocess.check_output([
                    'cryptsetup', 'luksOpen', f'{device}p1', 'luks', password
                ])
                output = subprocess.check_output([
                   'mount', f'/dev/mapper/luks', partition
                ])

        return mount_point

    def unmount(self, mount_point, password=None):
        """
        Unmount the disk image from the filesystem.

        :param mount_point: The path where the image is mounted.
        :param password: The password to use for encrypted images.
        """
        mount_points = []
        for root, dirs, _ in os.walk(mount_point):
            for dir in dirs:
                mount_points.append(os.path.join(root, dir))

        for point in mount_points:
            if os.path.ismount(point):
                try:
                    output = subprocess.check_output([
                       'sync'
                    ])
                    subprocess.check_output([
                        'umount', point
                    ])
                except subprocess.CalledProcessError:
                    if not password:
                        raise Exception("Password is required to unmount encrypted partitions.")
                    device = os.readlink(f'{point}/../device')
                    output = subprocess.check_output([
                        'cryptsetup', 'luksClose', device
                    ])

            try:
                output = subprocess.check_output([
                    'kpartx', '-d', f'{mount_point}/image.qcow2'
                ])
            except FileNotFoundError:
                raise Exception("kpartx not found. Please install it.")

            try:
                output = subprocess.check_output([
                    'rmdir', mount_point
                ])
            except FileNotFoundError:
                raise Exception(f"Directory '{mount_point}' does not exist.")

        return mount_point

    def extract(self, directory):
        """
        Extract all files from the disk image to the given directory.

        :param directory: The path to extract the files to.
        """
        with tempfile.TemporaryDirectory() as mount_point:
            self.mount(mount_point)
            with tarfile.open(f'{mount_point}/files.tar.gz', 'r:*') as tar:
                tar.extractall(path=directory)
            self.unmount(mount_point)

