    def __init__(self, artifact_path, extraction_dir):
        self.artifact_path = artifact_path
        self.extraction_dir = extraction_dir

    def unpack_targz(self):
        """Unpack targz artifact."""
        if not self.artifact_path.endswith('.tar.gz'):
            raise ValueError('Artifact is not a gzipped tarball')

        with tarfile.open(self.artifact_path, 'r:gz') as tarball:
            tarball.extractall(self.extraction_dir)

    def unpack_zip(self):
        """Unpack zip artifact."""
        if not self.artifact_path.endswith('.zip'):
            raise ValueError('Artifact is not a zip file')

        with zipfile.ZipFile(self.artifact_path, 'r') as zip_ref:
            zip_ref.extractall(self.extraction_dir)

    def unpack(self):
        """Unpack the artifact based on its extension."""
        if self.artifact_path.endswith('.tar.gz'):
            self.unpack_targz()
        elif self.artifact_path.endswith('.zip'):
            self.unpack_zip()
        else:
            raise ValueError('Unsupported artifact format')


