    def run_benchmark(self, func, *args, **kwargs):
        self.logger.start_benchmark(func.__name__)
        result = func(*args, **kwargs)
        self.logger.stop_benchmark(func.__name__)
        return result

    def save_benchmark_results(self, filename):
