import os
import datetime
import shutil
import argparse

class FileBackup:
    def __init__(self, source_dir, target_dir):
        self.source_dir = source_dir
        self.target_dir = target_dir

    def backup(self):
        for root, dirs, files in os.walk(self.source_dir):
            for file in files:
                file_path = os.path.join(root, file)
                target_path = os.path.join(self.target_dir, os.path.relpath(file_path, self.source_dir))
                shutil.copy2(file_path, target_path)
                print(f"Backed up {file_path} to {target_path}")

    def cleanup(self):
        for root, dirs, files in os.walk(self.target_dir):
            for file in files:
                file_path = os.path.join(root, file)
                if datetime.datetime.fromtimestamp(os.path.getctime(file_path)) < datetime.datetime.now() - datetime.timedelta(days=30):
                    os.remove(file_path)
                    print(f"Deleted old backup {file_path}")

def main():
    parser = argparse.ArgumentParser(description="File backup and cleanup script")
    parser.add_argument("-s", "--source", help="source directory to backup", required=True)
    parser.add_argument("-t", "--target", help="target directory for backups", required=True)
    args = parser.parse_args()

    if not os.path.exists(args.target):
        os.makedirs(args.target)

    backup = FileBackup(args.source, args.target)
    backup.backup()
    backup.cleanup()

if __name__ == "__main__":
    main()
