        self.mount_point = mount_point
        self.filesystem_id = None
        self.files = {}

    def _mount(self):
        if not os.path.exists(self.mount_point):
            subprocess.run(
                ["mkdir", "-p", self.mount_point],
                check=True,
            )
            self.filesystem_id = tempfile.mkstemp(dir=self.mount_point)[1]
            subprocess.run(
                ["tmpfs", "--mount_options=uid=1000,gid=1000,size=100M", "./tmpfs", self.mount_point],
                check=True,
            )
        else:
            self.filesystem_id = self.mount_point

    def _sync_and_umount(self):
        if self.filesyste_id:
            subprocess.run(
                ["sync"],
                check=True,
            )
            subprocess.run(
                ["umount", self.filesystem_id],
                check=True,
            )
            os.unlink(self.filesystem_id)
            os.rmdir(self.mount_point)

    def _compress_file(self, file_path):
        subprocess.run(
            ["xz", "-9", "-z", "-f", file_path],
            check=True,
        )

    def _decompress_file(self, archive_path, dest_path):
