        lines = self.extract_lines()
        uncovered_lines = []
        for node in lines:
            if isinstance(node, ast.For):
                # Handle for loops
                for line in node.body:
                    if isinstance(line, ast.Expr) and isinstance(line.value, ast.Str):
                        uncovered_lines.append(node.lineno)
            elif isinstance(node, ast.FunctionDef):
                # Handle function definitions
                uncovered_lines.append(node.lineno)
            elif isinstance(node, ast.If):
                # Handle if statements
                if not isinstance(node.test, ast.Constant) or node.test.value:
                    uncovered_lines.append(node.lineno)
        return [line for line in uncovered_lines if line not in coverage_data]

