import os
import sys

class CodeAnalyzer(ast.NodeVisitor):
    def __init__(self, max_lines, max_complexity):
        self.max_lines = max_lines
        self.max_complexity = max_complexity
        self.output = []

    def generic_visit(self, node):
        if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
            self.visit(node)
        super().generic_visit(node)

    def visit_FunctionDef(self, node):
        if len(node.body) > self.max_lines or self.calculate_complexity(node) > self.max_complexity:
            self.output.append({
                'file': os.path.basename(node.lineno[0].lineno),
                'function': node.name,
                'lines': len(node.body),
                'complexity': self.calculate_complexity(node),
                'location': self.get_location(node.lineno[0])
            })

    def visit_ClassDef(self, node):
        for method in node.body:
            if isinstance(method, ast.FunctionDef):
                if len(method.body) > self.max_lines or self.calculate_complexity(method) > self.max_complexity:
                    self.output.append({
                        'file': os.path.basename(node.lineno[0].lineno),
                        'function': node.name,
                        'lines': len(method.body),
                        'complexity': self.calculate_complexity(method),
                        'location': self.get_location(method.lineno[0])
                    })

    def calculate_complexity(self, node):
        complexity = 1
        for child in ast.walk(node):
            if isinstance(child, ast.Name):
                complexity += 1
            elif isinstance(child, ast.If) or isinstance(child, ast.For) or isinstance(child, ast.While):
                complexity += 3
            elif isinstance(child, ast.ListComp) or isinstance(child, ast.DictComp) or isinstance(child, ast.SetComp):
                complexity += 5
            elif isinstance(child, ast.Lambda):
                complexity += 2
        return complexity

    def get_location(self, node):
        return f'{node.lineno[0].lineno}:{node.lineno[0].col_offset}'

def analyze_code(filename, max_lines=10, max_complexity=10):
    with open(filename, 'r') as file:
        try:
            tree = ast.parse(file.read())
        except SyntaxError as e:
            return f'Error parsing file: {e}'

    analyzer = CodeAnalyzer(max_lines, max_complexity)
    analyzer.visit(tree)
    return analyzer.output

def main():
    parser = argparse.ArgumentParser(description='Code analyzer')
    parser.add_argument('file', help='file path to analyze')
    parser.add_argument('--max-lines', type=int, default=10, help='max allowed lines in a function')
    parser.add_argument('--max-complexity', type=int, default=10, help='max allowed complexity')
    args = parser.parse_args()

    issues = analyze_code(args.file, args.max_lines, args.max_complexity)
    if issues:
        for issue in issues:
            print(f'File: {issue["file"]}')
            print(f'Function: {issue["function"]}')
            print(f'Lines: {issue["lines"]}')
            print(f'Complexity: {issue["complexity"]}')
