import os

class DiskUsageAnalyzer:
    def __init__(self, path):
        self.path = path
        self.large_files = []

    def get_disk_usage(self):
        self.total_size = 0
        for root, dirs, files in os.walk(self.path):
            for f in files:
                filepath = os.path.join(root, f)
                size = os.path.getsize(filepath)
                self.total_size += size
                self._check_large_file(filepath, size)
        return self.total_size

    def _check_large_file(self, filepath, size):
        if size > 100 * 1024 * 1024:
            self.large_files.append((filepath, size))
        elif size > 10 * 1024 * 1024:
            print(f'Large file found: {filepath} - {size} bytes')

    def report_large_files(self):
        for filepath, size in self.large_files:
            print(f'Large file found: {filepath} - {size} bytes')


def main():
