class FileWriter:
    def __init__(self):
        self.config = configparser.ConfigParser()
        self.config.read('backup_config.ini')

    def backup_file(self, source, target):
        try:
            shutil.copy(source, target)
            print(f'File {source} copied to {target}')
        except Exception as e:
            print(f'Error copying file: {e}')

    def backup_dir(self, source, target):
        try:
            shutil.copytree(source, target)
            print(f'Directory {source} copied to {target}')
        except Exception as e:
            print(f'Error copying directory: {e}')

    def configure_backup(self):
        if not os.path.exists('backup_config.ini'):
            self.config['DEFAULT'] = {
               'source_dir': '/path/to/source',
                'target_dir': '/path/to/target',
            }
            with open('backup_config.ini', 'w') as configfile:
                self.config.write(configfile)

def main():
    parser = argparse.ArgumentParser(description='Backup files and directories')
    parser.add_argument('--source', help='Source directory or file')
    parser.add_argument('--target', help='Target directory')
    args = parser.parse_args()

    if not args.source or not args.target:
        print('Error: source and target directories must be specified')
        return

    if os.path.isdir(args.source):
        config = FileWriter()
        config.configure_backup()
        config.backup_dir(args.source, config.config['DEFAULT']['target_dir'] + '/' + os.path.basename(args.source) + '_' + datetime.now().strftime('%Y-%m-%d_%H-%M-%S') + '.backup')
    else:
        config = FileWriter()
        config.configure_backup()
        config.backup_file(args.source, config.config['DEFAULT']['target_dir'] + '/' + os.path.basename(args.source))

if __name__ == "__main__":
