import requests
import os
import shutil
import tarfile

class SpecialEffectsDownloader:
    def __init__(self, plugin_name, plugin_url, download_path):
        self.plugin_name = plugin_name
        self.plugin_url = plugin_url
        self.download_path = download_path

    def download_plugin(self):
        try:
            response = requests.get(self.plugin_url, stream=True)
            response.raise_for_status()
            with open(os.path.join(self.download_path, f"{self.plugin_name}.tar.gz"), "wb") as file:
                for chunk in response.iter_content(chunk_size=1024):
                    file.write(chunk)
            return True
        except requests.RequestException as e:
            print(f"Failed to download plugin: {e}")
            return False

    def extract_plugin(self):
        try:
            with tarfile.open(os.path.join(self.download_path, f"{self.plugin_name}.tar.gz"), "r:gz") as tar:
                tar.extractall(self.download_path)
            return True
        except tarfile.TarError as e:
            print(f"Failed to extract plugin: {e}")
            return False

class PluginInstaller:
    def __init__(self, download_path):
        self.download_path = download_path

    def install_plugin(self):
        try:
            plugin_dir = os.path.join(self.download_path, self.plugin_name)
            if os.path.exists(self.download_path) and os.path.isdir(plugin_dir):
                shutil.copytree(plugin_dir, "/usr/local/plugins")
            return True
        except FileExistsError as e:
            print(f"Failed to install plugin: {e}")
            return False

def main():
    plugin_name = input("Enter plugin name: ")
    plugin_url = input("Enter plugin URL: ")
    download_path = input("Enter download path: ")

    downloader = SpecialEffectsDownloader(plugin_name, plugin_url, download_path)
    if downloader.download_plugin():
        print("Plugin downloaded successfully")
        installer = PluginInstaller(download_path)
        installer.plugin_name = plugin_name
        if installer.install_plugin():
            print("Plugin installed successfully")
        else:
            print("Failed to install plugin")
    else:
        print("Failed to download plugin")

if __name__ == "__main__":
    main()
