class WebsiteCrawler:
    def __init__(self, start_url, timeout=5):
        self.start_url = start_url
        self.timeout = timeout
        self.links_queue = [self.start_url]
        self.broken_links = []
        self.missing_images = []

    def get_content(self, url):
        try:
            response = requests.get(url, timeout=self.timeout)
            response.raise_for_status()
            return response.text
        except requests.RequestException as e:
            self.broken_links.append(url)
            return None

    def extract_links(self, soup):
        return [url.get('href') for url in soup.find_all('a', href=True)]

    def extract_img_url(self, soup):
        return [url.get('src') for url in soup.find_all('img')]

    def is_valid(self, url):
        try:
            result = urlparse(url)
            return all([result.scheme, result.netloc])
        except ValueError:
            return False

    def crawl(self):
        while self.links_queue:
            url = self.links_queue.pop(0)
            content = self.get_content(url)
            if content is not None:
                soup = BeautifulSoup(content, 'html.parser')
                links = self.extract_links(soup)
                images = self.extract_img_url(soup)
                for link in links:
                    link = urljoin(url, link)
                    if self.is_valid(link):
                        self.links_queue.append(link)
                for image in images:
                    image = urljoin(url, image)
                    if not Path(image).exists() and self.is_valid(image):
                        self.missing_images.append(image)
        return {'broken_links': self.broken_links,'missing_images': self.missing_images}

