from typing import Dict, Set
import os
import coverage

def annotate_code(coverage_file: str, source_file: str, new_tests: Set[str]) -> None:
    """Annotate code based on test coverage results and new tests requirements"""

    # Get coverage data
    cov = coverage.Coverage(file=True)
    cov.load()

    # Get functions in the code that are not covered by tests
    uncovered_functions = {}
    with open(source_file, 'r') as file:
        for line_num, line in enumerate(file):
            for word in line.split():
                if word.startswith('def') and '(' in word and ')' in word:
                    func_name = word.split('(')[0].split()[-1]
                    covered = cov.get_context(line_num).covered
                    if 'def' in line and not covered:
                        uncovered_functions[func_name] = line_num

    # Annotate uncovered functions
    if uncovered_functions:
        print(f"Identified uncovered functions: {uncovered_functions}")

        # Annotate code
        code_to_write = ""
        with open(source_file, 'r') as file:
            for line_num, line in enumerate(file):
                if line_num in [func[1] for func in uncovered_functions.items()]:
                    permission ='# TODO: Requires test implementation: permission'
                    code_to_write += permission + "\n"
                else:
                    code_to_write += line
        with open(source_file, 'w') as file:
            file.write(code_to_write)
        print("Code annotated with TODO permission for uncovered functions")

    # Check if there are any new tests required
    if new_tests:
        print(f"Running tests: {new_tests}")
        run_results = [path for path in new_tests]
        cov.erase()
        cov.start()
        for path in run_tests(new_tests):
            cov.stop()
            cov.save()
            os.system('coverage html')
            if cov.report() == 100:
                run_results.append('Passed')
            else:
                run_results.append('Failed')
        return run_results
    else:
        print("No new tests required to run")

def run_tests(tests: Set[str]) -> list[str]:
    """Run the given set of test files"""
    import unittest
    test_suite = unittest.TestSuite()
    for test in tests:
        test_loader = unittest.TestLoader().loadTestsFromName(test)
        test_suite.addTests(test_loader.loadTestsFromName(test))
    runner = unittest.TextTestRunner()
    result = runner.run(test_suite)
    return [f"{test.id():15}  - {result.result()}" for test in tests]

class TestExample:
    def test_add(self):
        assert 2 + 2 == 4

    def test_divide(self):
        assert 4 / 2 == 2

if __name__ == "__main__":
    coverage_file = "coverage.xml"
    source_file = "example.py"
    new_tests = {TestExample()}
    annotate_code(coverage_file, source_file, new_tests)
