class JSONCSVConverter:
    def __init__(self, json_data: str, csv_file_path: str):
        self.json_data = json_data
        self.csv_file_path = csv_file_path

    def load_json(self):
        try:
            return json.loads(self.json_data)
        except json.JSONDecodeError as e:
            raise ValueError("Invalid JSON") from e

    def dump_json(self, data: Dict):
        return json.dumps(data, indent=4)

    def convert_json_to_csv(self):
        data = self.load_json()
        if not isinstance(data, dict):
            raise ValueError("Invalid JSON data")

        with open(self.csv_file_path, 'w', newline='') as file:
            writer = csv.writer(file)
            writer.writerow(list(data.keys()))
            for key, value in data.items():
                if isinstance(value, list):
                    for item in value:
                        writer.writerow([key] + item)
                else:
                    writer.writerow([key, value])

    def load_csv(self) -> List[Dict]:
        try:
            with open(self.csv_file_path, 'r') as file:
                reader = csv.DictReader(file)
                return [row for row in reader]
        except FileNotFoundError:
            raise FileNotFoundError("CSV file not found")

    def convert_csv_to_json(self):
        data = self.load_csv()
        for row in data:
            for key in row:
                row[key] = str(row[key]).replace('"', "'")
        return self.dump_json(data)

class Util:
    @classmethod
    def convert_json_to_csv(cls, json_data: str, csv_file_path: str):
        converter = JSONCSVConverter(json_data, csv_file_path)
        converter.convert_json_to_csv()

    @classmethod
    def convert_csv_to_json(cls, csv_file_path: str):
        converter = JSONCSVConverter('', csv_file_path)
        return converter.convert_csv_to_json()

