import json
import os
import threading
from datetime import datetime, timedelta

class CacheServer:
    def __init__(self, cache_dir, max_cache_size):
        self.cache_dir = cache_dir
        self.max_cache_size = max_cache_size
        self.lock = threading.Lock()

        if not os.path.exists(cache_dir):
            os.makedirs(cache_dir)

    def _get_cache_file_path(self, key):
        return os.path.join(self.cache_dir, f"{hashlib.md5(key.encode()).hexdigest()}.json")

    def store_url(self, url, response):
        with self.lock:
            data = {
                "headers": response.headers,
                "body": response.read(),
                "timestamp": int(datetime.now().timestamp())
            }

            key = hashlib.md5(url.encode()).hexdigest()

            cache_file_path = self._get_cache_file_path(key)
            with open(cache_file_path, "w") as file:
                json.dump(data, file)

            self._clean_cache()

    def get_url(self, url):
        with self.lock:
            key = hashlib.md5(url.encode()).hexdigest()
            cache_file_path = self._get_cache_file_path(key)

            if os.path.exists(cache_file_path):
                with open(cache_file_path, "r") as file:
                    data = json.load(file)
                    timestamp = data["timestamp"]

                    if (datetime.now() - datetime.fromtimestamp(timestamp)).total_seconds() < 300:  # Cache for 5 minutes
                        return http.client.HTTPResponse(data["headers"], data["body"])
                    else:
                        os.remove(cache_file_path)

            return None

    def _clean_cache(self):
        while True:
            files = os.listdir(self.cache_dir)
            current_size = sum(os.path.getsize(os.path.join(self.cache_dir, file)) for file in files)
            if current_size < self.max_cache_size:
                break

            oldest_file = min(files, key=lambda file: os.path.getctime(os.path.join(self.cache_dir, file)))
            os.remove(os.path.join(self.cache_dir, oldest_file))

def serve_request(url):
    connection = http.client.HTTPConnection(url.split("://")[-1].split("/")[0])
    connection.request("HEAD", url.split("://")[-1].split("?")[0])
    response = connection.getresponse()
    return response

class CacheMiddleware:
    def __init__(self, cache_server, host, port):
        self.cache_server = cache_server
        self.host = host
        self.port = port

    def process_request(self, url):
        cached_response = self.cache_server.get_url(url)
        if cached_response:
            return cached_response

        response = serve_request(url)
        self.cache_server.store_url(url, response)
        return response

    def process_response(self, request, response):
        return response

def main():
    cache_dir = "cache"
    cache_server = CacheServer(cache_dir, 1024 * 1024 * 1024)  # 1GB cache size

    cache_proxy = CacheMiddleware(cache_server, "www.example.com", 80)

    while True:
        url = input("Enter a URL to fetch (or leave blank to exit): ")
        if not url:
            break

        cached_response = cache_proxy.process_request(url)
        if not cached_response:
            print("URL not found in cache. Fetching from origin server...")
        else:
            print("Fetched from cache.")

        for key, value in cached_response.headers.items():
            print(f"{key}: {value}")
            print("------")

main()
```
This is a basic implementation of a web cache server using a simple disk-based cache storage. The cache is cleaned periodically when the current cache size exceeds the maximum specified size. The cache stores HTTP responses from the origin server and serves them directly from cache when the same URL is requested again within the cache's TTL (5 minutes in this case). 

The example usage is in the `main` function, where it creates an instance of CacheServer with a 1GB cache size and uses it as a proxy to fetch URLs from a server.

