    backups: List[Backup]
    total_space_used: float

class BackupSystem:
    def __init__(self, backup_dir: str):
        self.backup_dir = backup_dir
        self.backups = []

    def create_backup(self, backup_id: str):
        filename = f'{backup_id}.tar.gz'
        tar_path = os.path.join(self.backup_dir, filename)
        os.system(f'tar -czf {tar_path} {backup_id}')
        file_size = os.path.getsize(tar_path)
        self.backups.append(Backup(backup_id, filename, datetime.now().isoformat(), os.path.join(self.backup_dir, filename), file_size))
        return Backup(backup_id, filename, datetime.now().isoformat(), tar_path, file_size)

    def list_backups(self) -> List[Backup]:
        backups = []
        for filename in os.listdir(self.backup_dir):
            if filename.endswith('.tar.gz'):
                file_path = os.path.join(self.backup_dir, filename)
                size = os.path.getsize(file_path)
                backups.append(Backup(os.path.splitext(filename)[0], filename, os.path.getmtime(file_path).isoformat(), file_path, size))
        return sorted(backups, key=lambda x: x.date, reverse=True)

    def restore_backup(self, backup_id: str):
        for backup in self.backups:
            if backup.id == backup_id:
                os.system(f'tar -xzf {backup.tarball_path}')
                return

    def get_backup_report(self) -> BackupReport:
        backups = self.list_backups()
        total_space_used = sum(backup.size for backup in backups)
        return BackupReport(backups, total_space_used)

