        elif self.tarball_type == "zip":
            with zipfile.ZipFile(self.output_file, 'w') as zip_file:
                for dirpath, _, filenames in os.walk(self.input_dir):
                    for filename in filenames:
                        filepath = str(Path(dirpath) / filename)
                        rel_path = os.path.relpath(filepath, self.input_dir)
                        zip_file.write(filepath, rel_path)

