class PeeringClient:
    def __init__(self, file_name, peers, chunk_size=1024):
        self.file_name = file_name
        self.peers = peers
        self.chunk_size = chunk_size
        self.chunks_completed = 0
        self.chunk_queue = Queue()

    def download_chunk(self, peer, chunk_id):
        response = requests.get(f'http://{peer}:8000/{self.file_name}', headers={'Range': f'bytes={chunk_id * self.chunk_size}-{(chunk_id + 1) * self.chunk_size - 1}'})

        if response.status_code == 206:
            self.chunk_queue.put((response.text, chunk_id))
        else:
            print(f'Error downloading chunk {chunk_id} from {peer}')

    def start_download(self):
        threads = []

        for peer in self.peers:
            thread = threading.Thread(target=self.download_chunk, args=(peer, self.chunks_completed // self.chunk_size))
            threads.append(thread)
            thread.start()

        for thread in threads:
            thread.join()

        chunks = []

        while not self.chunk_queue.empty():
            chunks.append(self.chunk_queue.get())

        with open(self.file_name, 'wb') as file:
            for chunk, chunk_id in chunks:
                file.write(chunk)

        print('File downloaded successfully!')

    def verify_checksum(self):
        file_size = 0
        with open(self.file_name, 'rb') as file:
            for _ in file:
                file_size += len(_)

        expected_size = 0
        for peer in self.peers:
            for _ in requests.get(f'http://{peer}:8000/size/{self.file_name}').text:
                expected_size += _.split(':')[1]

        if file_size >= expected_size:
            print('File verified successfully!')
        else:
            print('File verification failed!')

