import tarfile
import argparse
import os
import shutil

def create_backup(input_path, output_path):
    """Create a tar archive from a specified directory or file."""
    if os.path.isdir(input_path):
        # Add the entire directory and its contents to the tar file
        with tarfile.open(output_path, "w:gz") as tar:
            tar.add(input_path)
    elif os.path.isfile(input_path):
        # Add a file to the tar file
        with tarfile.open(output_path, "w:gz") as tar:
            tar.add(input_path)
    else:
        raise ValueError("The input path must be a directory or a file")

def extract_backup(input_path, destination_path):
    """Extract the contents of a tar archive to a specified directory."""
    try:
        with tarfile.open(input_path, "r:gz") as tar:
            tar.extractall(destination_path)
    except FileNotFoundError:
        print("The specified backup file does not exist")
    except Exception as e:
        print(f"An error occurred while extracting the backup: {e}")

def main():
    parser = argparse.ArgumentParser(description="Create or restore a backup")
    parser.add_argument("-c", "--create", action="store_true", help="Create a backup")
    parser.add_argument("-r", "--restore", action="store_true", help="Restore a backup")
    parser.add_argument("-i", "--input", type=str, help="Path to input file or directory")
    parser.add_argument("-o", "--output", type=str, help="Path to the output file")
    parser.add_argument("-d", "--destination", type=str, help="Destination path for restored backup")
    args = parser.parse_args()

    if args.create:
        create_backup(args.input, "backup.tar.gz")
    elif args.restore:
        if args.output:
            shutil.copy("backup.tar.gz", args.output)
        extract_backup("backup.tar.gz", args.destination)
    else:
        parser.print_help()

if __name__ == "__main__":
