                if item.name.endswith('.mp3'):
                    extract_path = os.path.join(os.getcwd(), item.name)
                    tar.extract(item, path=os.getcwd())
                    with open(extract_path, 'rb') as f_in, open('tracks.mp3', 'wb') as f_out:
