            root_src = pathlib.Path(src)
        else:
            root_src = pathlib.Path(root)

        for root, _, files in os.walk(root_src):
            for file in files:
                file_path = os.path.join(root, file)
                rel_path = os.path.relpath(file_path, root_src)
                z.write(file_path, arcname=rel_path)

def tar_backup(root, src=None, compressed=False):
