import zipfile
import os
import shutil

class AppPackager:
    def __init__(self, app_directory):
        self.app_directory = app_directory

    def package_app(self, archive_name):
        with zipfile.ZipFile(archive_name, 'w') as zip_file:
            for root, dirs, files in os.walk(self.app_directory):
                for file in files:
                    path = os.path.join(root, file)
                    rel_path = os.path.relpath(path, start=self.app_directory)
                    zip_file.write(path, rel_path)

    def unpack_app(self, archive_name, output_directory):
        with zipfile.ZipFile(archive_name, 'r') as zip_file:
            zip_file.extractall(output_directory)

class AppInstaller:
    def __init__(self, package):
        self.package = package

    def install(self):
        original_dir = self.package.app_directory
        output_dir = f"{original_dir}_unpacked"
        if not os.path.exists(output_dir):
            os.makedirs(output_dir)
        self.package.unpack_app(self.package.app_directory + '.zip', output_dir)
        os.replace(output_dir, original_dir)

# Usage example:
package = AppPackager(r'/path/to/app')
package.package_app('my_app.zip')
installer = AppInstaller(package)
installer.install()
