def extract_classes(source_code):
    classes = []
    for line in source_code.split('\n'):
        if 'class' in line:
            class_name = line.split('class ')[1].split(':')[0]
            classes.append(class_name)
    return classes

# Define a function to extract methods from source code
def extract_methods(source_code):
    methods = set()
    for line in source_code.split('\n'):
        if 'def' in line:
            method_name = line.split('def ')[1].split('(')[0]
            methods.add(method_name)
    return methods

# Define a function to generate UML diagram from extracted classes and methods
def generate_uml_diagram(classes, methods):
    graph = AGraph(directed=True, format='dot')
    for class_name in classes:
        node = graph.add_node(class_name)
        node.attr['shape'] = 'box'
        for method in methods:
            if method.startswith(class_name):
                edge = graph.add_edge(class_name, method)
                edge.attr['style'] = 'dotted'
    return graph

# Define a function to save the diagram as an image file
def save_diagram(graph, filename):
    try:
        graph.format = 'png'
        graph.render(filename, view=True, cleanup=True)
        os.chmod(filename, 0o644)
    except Exception as e:
        print(f'Failed to save diagram: {e}')

# Define a function to analyze source code and generate UML diagram
def analyze_source_code(source_code, filename, permissions):
    classes = extract_classes(source_code)
    methods = extract_methods(source_code)
    graph = generate_uml_diagram(classes, methods)
    save_diagram(graph, f'{filename}.png')
    for permission in permissions:
