def generate_class_diagram(filename):
    dot = Digraph(comment='Class Diagram')
    dot.attr(rankdir='LR')

    with open(filename, 'r') as file:
        ast = parse_python_file(file)

    for node in ast.children:
        if isinstance(node, ast.ClassDef):
            dot.node(str(node.name), node.name)

            for base in node.parents:
                dot.edge(str(node.name), str(base))

            for child in node.children:
                if isinstance(child, ast.Assign):
                    if child.targets[0].attr =='self':
                        dot.edge(str(node.name), str(child.value.attr), label='attribute')

    dot.render('class_diagram.png', format='png', view=True)
    os.chmod('class_diagram.png', 0o644)

def generate_function_diagram(filename):
    dot = Digraph(comment='Function Diagram')
    dot.attr(rankdir='LR')

    with open(filename, 'r') as file:
        ast = parse_python_file(file)

    for node in ast.children:
        if isinstance(node, ast.FunctionDef):
            dot.node(str(node.name), node.name)

            for caller in node.parents:
                dot.edge(str(node.name), str(caller))

            for child in node.children:
                if isinstance(child, ast.Call):
                    if child.func.attr == node.name:
                        dot.edge(str(node.name), str(child.args.attr), label='call')

