import os
import hashlib

class VersionControl:
    def __init__(self, root_dir='repo'):
        self.root_dir = root_dir
        self.files = {}

    def add_file(self, filename, content):
        current_hash = hashlib.sha256(content.encode()).hexdigest()
        if filename not in self.files:
            with open(os.path.join(self.root_dir, filename), 'w') as f:
                f.write(content)
            self.files[filename] = ['current', current_hash]
        else:
            raise FileExistsError(f"File {filename} already exists")

    def update_file(self, filename, content):
        current_hash = hashlib.sha256(content.encode()).hexdigest()
        if filename in self.files:
            self.files[filename] = ['current', current_hash]
            with open(os.path.join(self.root_dir, filename), 'w') as f:
                f.write(content)
        else:
            raise FileNotFoundError(f"File {filename} does not exist")

    def merge_changes(self, filename, new_content):
        if filename in self.files:
            history = self.records_history(filename)
            if history[:2] == ['merge', 'current']:
                self.update_file(filename, new_content)
            else:
                raise ValueError(f"Cannot merge changes into this file, has been modified")
        else:
            raise FileNotFoundError(f"File {filename} does not exist")

    def records_history(self, filename):
        try:
            with open(os.path.join(self.root_dir, filename), 'r') as f:
                content = f.readline()
                while content:
                    yield content.strip()
                    content = f.readline()
        except FileNotFoundError:
            pass

    def get_file_content(self, filename):
        if filename in self.files:
            try:
                with open(os.path.join(self.root_dir, filename), 'r') as f:
                    return f.read()
            except FileNotFoundError:
                pass
        else:
            raise FileNotFoundError(f"File {filename} does not exist")
