from functools import partial

def extract_tarball(tarball_path, output_dir):
    with tarfile.open(tarball_path, 'r:gz') as tar:
        members = [member for member in tar.getmembers() if member.isfile()]
        tar.extractall(path=output_dir, members=members)

def extract_zip_file(zip_file_path, output_dir):
    with zipfile.ZipFile(zip_file_path, 'r') as zip_ref:
        zip_ref.extractall(output_dir)

def extract_dependencies(tarball_path, output_dir, extract_func=extract_tarball):
    if tarball_path.endswith('.tar.gz'):
        return extract_func(tarball_path, output_dir)
    elif tarball_path.endswith('.zip'):
        return extract_zip_file(tarball_path, output_dir)
    else:
        raise ValueError('Invalid archive type')

def deploy_dependencies(tarballs, output_dir, n_jobs=None):
    with multiprocessing.Pool(processes=n_jobs) as pool:
        pool.map(partial(extract_dependencies, output_dir=output_dir), tarballs)
    return output_dir

def main():
    tarballs = ['path/to/tarball1.tar.gz', 'path/to/tarball2.zip']
    output_dir = 'output/directory'
    n_jobs = multiprocessing.cpu_count()

    output_dir = deploy_dependencies(tarballs, output_dir, n_jobs)
