import tarfile

class TarBrowser:
    def __init__(self, tarball_path):
        self.tarball_path = tarball_path

    def list_files(self):
        with tarfile.open(self.tarball_path, 'r:gz') as tar:
            for file_info in tar.getmembers():
                print(f"File: {file_info.name}, Size: {file_info.size}, Type: {file_info.isdir() and 'Directory' or 'File'}")

    def browse_file(self):
        parser = argparse.ArgumentParser(description='Browse tarball')
        parser.add_argument('tarball_path', help='Path to tarball')
        parser.add_argument('--file', help='Path to a file within the tarball', type=str)
        args = parser.parse_args()

        if args.file:
            try:
                with tarfile.open(args.tarball_path, 'r:gz') as tar:
                    file_info = tar.extractfile(args.file)
                    if file_info:
                        print(f"File {args.file} extracted successfully")
                    else:
                        print(f"File {args.file} not found in the tarball")
            except (OSError, tarfile.ReadError) as e:
                print(f"An error occurred: {e}")
        else:
            self.list_files()

if __name__ == '__main__':
    browser = TarBrowser('path_to_your_tarrball.tar.gz')
    browser.browse_file()
