import os
import tarfile
import argparse
import shutil

def create_backup(root_path, output_path="backup.tar", exclude_dirs=[".git", "__pycache__"]):
    try:
        with tarfile.open(output_path, "w") as tar:
            tar.add(root_path, arcname=os.path.basename(root_path), exclude=exclude_dirs)
        print(f"Backup created at: {output_path}")
    except tarfile.TarError as e:
        print(f"Error creating backup: {e}")

def extract_backup(input_path="backup.tar", output_path="."):
    try:
        with tarfile.open(input_path, "r") as tar:
            tar.extractall(path=output_path)
        print(f"Backup extracted to: {output_path}")
    except (FileNotFoundError, tarfile.TarError) as e:
        print(f"Error extracting backup: {e}")

def main():
    parser = argparse.ArgumentParser(description="Backup utility")
    parser.add_argument("mode", choices=["create", "extract"], help="Mode to operate in (create, extract)")
    parser.add_argument("--root-path", default=".", help="Root path to backup or extract")
    parser.add_argument("--output-path", help="Output path for backup file or extraction")
    args = parser.parse_args()

    if args.mode == "create":
        create_backup(args.root_path, args.output_path)
    elif args.mode == "extract":
        extract_backup(args.output_path, args.root_path)
    else:
        print("Invalid mode specified")

if __name__ == "__main__":
    main()
