class DiskImageRepository:
    def __init__(self, root_dir):
        self.root_dir = root_dir
        self.images = {}

    def add_image(self, image_name, tarball_path):
        if not tarball_path.endswith('.tar.gz'):
            raise ValueError("Tarball must be a.tar.gz file")

        with open(tarball_path, 'rb') as f:
            with tarfile.open(fileobj=f, mode='r:gz') as tar:
                try:
                    tar.extractall(path=os.path.join(self.root_dir, image_name))
                    self.images[image_name] = os.path.join(self.root_dir, image_name)
                except tarfile.ExtractError as e:
                    raise ValueError(f"Failed to extract tarball: {e}")

        return self.images[image_name]

    def get_image(self, image_name):
        if image_name in self.images:
            return self.images[image_name]
        else:
            raise ValueError(f"Image {image_name} not found")

    def delete_image(self, image_name):
        if image_name in self.images:
            path = self.images[image_name]
            try:
                os.rmdir(path)
                del self.images[image_name]
            except OSError as e:
                raise ValueError(f"Failed to remove image: {e}")
        else:
            raise ValueError(f"Image {image_name} not found")


# Example Usage
