import os
import hashlib
import datetime

class SourceControl:
    def __init__(self):
        self.revisions = {
            "files": {}
        }

    def add_file(self, file_path, content):
        file_hash = self._calculate_file_hash(file_path, content)
        if file_hash not in self.revisions["files"]:
            self.revisions["files"][file_hash] = {
                "file_path": file_path,
                "content": content,
                "revision_date": str(datetime.datetime.now()),
                "revisions": {}
            }
        self.revisions["files"][file_hash]["revisions"][self.get_revision_number()] = content

    def update_file(self, file_hash, new_content):
        if file_hash in self.revisions["files"]:
            self.revisions["files"][file_hash]["revisions"][self.get_revision_number()] = new_content

    def delete_file(self, file_hash):
        if file_hash in self.revisions["files"]:
            del self.revisions["files"][file_hash]

    def get_revision(self, file_hash):
        if file_hash in self.revisions["files"]:
            return self.revisions["files"][file_hash]

    def get_revision_number(self):
        if "current_revision" not in self.revisions:
            self.revisions["current_revision"] = 1
        else:
            self.revisions["current_revision"] += 1
        return self.revisions["current_revision"]

    def _calculate_file_hash(self, file_path, content):
        with open(file_path, "wb") as file:
            file.write(content.encode("utf-8"))
        file_hash = hashlib.sha256()
        file_hash.update(content.encode("utf-8"))
        return file_hash.hexdigest()

    def save(self, file_path):
        with open(file_path, "w") as file:
            import json
            json.dump(self.revisions, file, indent=4)

    def load(self, file_path):
        if os.path.exists(file_path):
            with open(file_path, "r") as file:
                self.revisions = json.load(file)
        else:
            self.__init__()

class RevisionControl:
    def __init__(self, file_path):
        self.source_control = SourceControl()
        self.revisions = {}
        if os.path.exists(file_path):
            self.source_control.load(file_path)

    def add(self, file_path, content):
        self.source_control.add_file(file_path, content)
        self.revisions[file_path] = self.source_control.get_revision_number() - 1
        self.save()

    def update(self, file_path, content):
        self.source_control.update_file(self.get_file_hash(file_path), content)
        self.revisions[file_path] = self.source_control.get_revision_number() - 1
        self.save()

    def delete(self, file_hash):
        self.source_control.delete_file(file_hash)
        for key, value in self.revisions.items():
            if key == file_hash:
                del self.revisions[key]

    def get(self, file_path):
        return self.source_control.get_revision(self.get_file_hash(file_path))

    def get_file_hash(self, file_path):
        for file_hash, file_data in self.source_control.revisions["files"].items():
            if file_data["file_path"] == file_path:
                return file_hash

    def save(self):
        self.source_control.save("database.json")
        with open("revisions.json", "w") as file:
            import json
            json.dump(self.revisions, file)

    def load(self):
        if os.path.exists("database.json"):
            self.source_control.load("database.json")
            with open("revisions.json", "r") as file:
                self.revisions = json.load(file)
        else:
            self.__init__()

