class CAD:
    def __init__(self):
        self.drawings = {}

    def add_drawing(self, name: str):
        if name in self.drawings:
            raise ValueError(f"Drawing '{name}' already exists")
        self.drawings[name] = Drawing(name, [])

    def add_line(self, name: str, x1: float, y1: float, x2: float, y2: float):
        if name not in self.drawings:
            raise ValueError(f"Drawing '{name}' does not exist")
        self.drawings[name].lines.append(Line(Point(x1, y1), Point(x2, y2)))

    def save_toproprietary_format(self, name: str, file_path: str):
        if name not in self.drawings:
            raise ValueError(f"Drawing '{name}' does not exist")
        with open(file_path, 'w') as f:
            f.write(self.drawings[name].name + '\n')
            for line in self.drawings[name].lines:
                f.write(f'Line from ({line.start.x}, {line.start.y}) to ({line.end.x}, {line.end.y})\n')

    def load_proprietary_format(self, file_path: str):
