            lines = f.readlines()
            name = lines[0].strip()
            self.add_drawing(name)
            for line in lines[1:]:
                x1, y1, x2, y2 = map(float, line.strip().split('to')[0].replace('(', '').replace(')', ''))
                self.add_line(name, x1, y1, x2, y2)

