    """Extract a zip archive."""
    with zipfile.ZipFile(file_path, 'r') as zip_ref:
        zip_ref.extractall()

def extract_rar(file_path):
    """Extract a rar archive."""
    with RarFile(file_path, 'r') as rar_ref:
        rar_ref.extractall()

def extract_tar(file_path):
    """Extract a tar archive."""
    with TarFile(file_path, 'r') as tar_ref:
        tar_ref.extractall()

def extract_pdf(file_path):
    """Extract pages from a pdf document."""
    with open(file_path, 'rb') as pdf_ref:
        try:
            reader = PdfReader(pdf_ref)
            for page in reader.pages:
                yield page.extract_text()
        finally:
            pdf_ref.close()

def extract_contents(file_path):
    """
    Extract the contents of a compressed archive.

    This function identifies the extension of the file and calls the
    corresponding extract function.
    """
    if file_path.endswith('.zip'):
        return extract_zip(file_path)
    elif file_path.endswith('.rar'):
        return extract_rar(file_path)
    elif file_path.endswith('.tar') or file_path.endswith('.gz') or file_path.endswith('.bz2') or file_path.endswith('.tar.gz'):
        return extract_tar(file_path)
    elif file_path.endswith('.pdf'):
        return extract_pdf(file_path)
    else:
        raise ValueError("Unsupported archive format")

