import argparse
import os
import re
import sys

class CodeAnalyzer:
    def __init__(self, file_paths, output_file=None):
        self.file_paths = file_paths
        self.output_file = output_file
        self.permitted_extensions = ['.py', '.java', '.cpp']

    def get_file_contents(self, file_path):
        try:
            with open(file_path, 'r') as file:
                return file.read()
        except Exception as e:
            print(f"Error reading {file_path}: {e}")
            return None

    def count_comments(self, file_contents):
        return re.findall(r'#.*|\/\/.*|/\*.*\*/', file_contents)

    def count_lines(self, file_contents):
        return file_contents.count('\n') + 1

    def analyze_code(self):
        for file_path in self.file_paths:
            if not file_path.endswith(tuple(self.permitted_extensions)):
                print(f"Skipping {file_path} (not a permitted type)")
                continue

            file_contents = self.get_file_contents(file_path)
            if not file_contents:
                continue

            comment_count = len(self.count_comments(file_contents))
            line_count = self.count_lines(file_contents)
            comment_density = comment_count / line_count

            print(f"File: {file_path}")
            print(f"Comment count: {comment_count}")
            print(f"Line count: {line_count}")
            print(f"Comment density: {comment_density:.4f}")
            print()

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description='Analyze code comments and calculate metrics')
    parser.add_argument('file_paths', nargs='+', help='Path to the files to analyze')
    parser.add_argument('-o', '--output', help='Write output to file instead of stdout')
    args = parser.parse_args()

    analyzer = CodeAnalyzer(args.file_paths, args.output)

    if args.output:
        with open(args.output, 'w') as output_file:
            analyzer.analyze_code()
            output_file.write(''.join(sys.stdout.getvalue()))
    else:
        analyzer.analyze_code()
