        self.output_dir = 'build'
        self.tarball_name = f'distribution_{self.timestamp}.tar.gz'
        self.argparser = argparse.ArgumentParser(description='Build System')
        self.argparser.add_argument('--root', help='The root directory to build from')
        self.argparser.add_argument('--output_dir', help='The directory to output the tarball')
        self.argparser.add_argument('--output_name', help='The name of the tarball')
        self.args = self.argparser.parse_args()

    def get_directory_contents(self, directory):
        contents = []
        for item in os.listdir(directory):
            item_path = os.path.join(directory, item)
            if os.path.isdir(item_path):
                contents.append((item, self.get_directory_contents(item_path)))
            else:
                contents.append(item)
        return contents

    def build(self):
        if not self.args.output_dir:
            self.output_dir = self.args.output_name = self.timestamp
        if not os.path.exists(self.output_dir):
            os.makedirs(self.output_dir)

        contents = self.get_directory_contents(self.args.root if self.args.root else '.')

        with open(os.path.join(self.output_dir, 'META-INF/MANIFEST.MF'), 'w') as f:
            for name, item in contents:
                f.write(f'{name}\n')

        with open(os.path.join(self.output_dir,'manifest.txt'), 'w') as f:
            for name, item in contents:
                f.write(f'{name}\n')

        with TarFile.open(self.tarball_name, mode='w:gz', dereference=False) as tar_file:
            for name, item in contents:
                if isinstance(item, list):
                    self.include_directory(tar_file, name, item)
                else:
                    self.include_file(tar_file, name, item)

        print(f'Tarball created: {self.tarball_name}')

    def include_file(self, tar_file, name, path):
        name = name + '/' + os.path.basename(path)
        with open(path, 'rb') as f:
            data = f.read()
        tar_file.addfile(TarInfo(os.path.basename(path)), data)

    def include_directory(self, tar_file, name, contents):
        with tar_file.open(name, 'w') as tar_stream:
            for item in contents:
                if isinstance(item, list):
                    self.include_directory(tar_file, name + '/', item)
                else:
