import PyPDF2
import pandas as pd

class PDFtoExcel:
    def __init__(self, pdf_file):
        self.pdf_file = pdf_file

    def extract_text(self):
        pdf_reader = PyPDF2.PdfReader(self.pdf_file)
        text = ''
        for page in pdf_reader.pages:
            text += page.extract_text()
        return text

    def split_into_tables(self, text):
        import re
        paragraphs = re.split(r'\n\n', text)
        tables = []
        for paragraph in paragraphs:
            lines = paragraph.split('\n')
            table = []
            for line in lines:
                cells = line.split('\t')
                if len(cells) > 1:
                    table.append(cells)
            if table:
                tables.append(table)
        return tables

    def convert_to_excel(self):
        text = self.extract_text()
        tables = self.split_into_tables(text)
        excel_data = pd.DataFrame()
        for table in tables:
            data = []
            for row in table:
                row_data = []
                for cell in row:
                    row_data.append(cell.strip() if cell else '')
                data.append(row_data)
            excel_data = pd.concat([excel_data,pd.DataFrame(data)], ignore_index=True)
        return excel_data

if __name__ == "__main__":
    pdf_file = 'example.pdf'
    pdf_reader = PDFtoExcel(pdf_file)
    excel_data = pdf_reader.convert_to_excel()
    excel_data.to_excel('output.xlsx', index=False)
