        with open(self.log_path, 'r') as f:
            for num, line in enumerate(f, 1):
                try:
                    _, status_code, _ = line.split('"', 2)
                    if '404' in status_code:
                        anchor = re.search(r'([^\s]+)\s', line).group(1)
                        self.anchors.setdefault(anchor, []).append(num)
                except ValueError:
                    pass

    def report_dead_links(self):
        for anchor, line_numbers in self.anchors.items():
            print(f"404 Error: {anchor}")
            print(f"Line Numbers: {', '.join(map(str, line_numbers))}")
            print()


def analyze_log(log_path):
    analyzer = WebLogAnalyzer(log_path)
    analyzer.read_log()
    analyzer.report_dead_links()


if __name__ == "__main__":
