                            continue
                        statements.append(line.strip())
        path = self.temp_dir / f"test_{test_name}.py"
        with open(path, "w") as f:
            f.write(template.render(test_name=test_name, statements=statements))

    def get_coverage(self, output=False):
        cov = coverage.Coverage()
        cov.start()
        if not output:
            input("Press Enter to continue after running test")
        else:
            os.system("pytest")
        cov.stop()
        cov.save()
        cov.report(file=output)

    def run(self, test_names):
        for name in test_names:
