from abc import ABC, abstractmethod
import logging
from pylint import epylint

class CodeAnalyzer:
    def __init__(self, source_code):
        self.source_code = source_code
        self.report = {}
        self.config = {}

    def set_config(self, config):
        self.config = config

    def analyze(self):
        self.report = self._analyze(self.source_code)

    def generate_report(self):
        return self._generate_report(self.report)

    @staticmethod
    def _analyze(source_code):
        try:
            report = epylint.process_tree(source_code)
            issue_types = ['R0902', 'R0903']  # long and complex methods

            report = {
                'issues': [
                    item for item in report if (item['symbol'] in issue_types)
                ],
                'violations': []
            }

            for issue in report['issues']:
                if issue['location'] is not None and issue['symbol'] == 'R0903' and len(issue['text']) > self.config['max_complexity']:
                    report['violations'].append({
                        'type': 'complexity',
                       'method': issue['text'],
                        'function': issue['location'][0],
                        'line': issue['location'][1],
                        'column': issue['location'][2],
                    })
                elif issue['location'] is not None and issue['symbol'] == 'R0902' and issue['estimate'] > self.config['max_length']:
                    report['violations'].append({
                        'type': 'length',
                       'method': issue['text'],
                        'function': issue['location'][0],
                        'line': issue['location'][1],
                        'column': issue['location'][2],
                    })

            return report
        except Exception as e:
            logging.error(f'Error analyzing code: {str(e)}')
            return {}

    @staticmethod
    def _generate_report(report):
        if report['issues']:
            return '\n'.join([
                f'**Method {item["type"]} Issue**: Function `{item["function"]}` at line {item["line"]}, column {item["column"]}: {item["method"]}'
                for item in report['violations']
            ])
        else:
            return 'No issues found'

def command_line_interface():
    import argparse

    parser = argparse.ArgumentParser()
    parser.add_argument('--max_length', type=int, default=5)
    parser.add_argument('--max_complexity', type=int, default=10)
    parser.add_argument('file', nargs='?', default='script.py')

    args = parser.parse_args()

    with open(args.file, 'r') as f:
        source_code = f.read()

    analyzer = CodeAnalyzer(source_code)
    analyzer.set_config({
       'max_length': args.max_length,
       'max_complexity': args.max_complexity
    })
    analyzer.analyze()
    print(analyzer.generate_report())

command_line_interface()
