import zipfile
import rarfile
import lzma
import os

class ArchiveExtractor:
    def __init__(self, archive_path):
        self.archive_path = archive_path

    def extract_zip(self):
        with zipfile.ZipFile(self.archive_path, 'r') as zip_ref:
            zip_ref.extractall()

    def extract_rar(self):
        with rarfile.RarFile(self.archive_path, 'r') as rar_ref:
            rar_ref.extractall()

    def extract_tar(self):
        with tarfile.TarFile(self.archive_path, 'r:gz') as tar_ref:
            tar_ref.extractall()

    def extract_gz(self):
        with gzip.GzipFile(self.archive_path, 'rb') as gz_ref:
            with tempfile.NamedTemporaryFile(mode='wb') as tmp_file:
                gz_ref.readinto(tmp_file.write)
                tmp_file.seek(0)
                shutil.copy(tmp_file.name, 'untitled')

    def extract_lzma(self):
        with lzma.open(self.archive_path, 'rb') as lzma_ref:
            with tempfile.NamedTemporaryFile(mode='wb') as tmp_file:
                lzma_ref.readinto(tmp_file.write)
                tmp_file.seek(0)
                shutil.copy(tmp_file.name, 'untitled')

    def extract(self):
        if self.archive_path.endswith('.zip'):
            self.extract_zip()
        elif self.archive_path.endswith('.rar'):
            self.extract_rar()
        elif self.archive_path.endswith('.tar.gz'):
            self.extract_tar()
        elif self.archive_path.endswith('.gz'):
            self.extract_gz()
        elif self.archive_path.endswith('.lzma'):
            self.extract_lzma()
        else:
            raise ValueError('Unsupported archive format')

if __name__ == '__main__':
