        if self.db_type =='sqlite':
            self._create_sqlite_backup()
        elif self.db_type == 'postgres':
            self._create_postgres_backup()
        elif self.db_type =='mysql':
            self._create_mysql_backup()

    def _create_sqlite_backup(self):
        try:
            with sqlite3.connect(self.db_name) as conn:
                with open(os.path.join(self.backup_path, f'{self.db_name}.db'), 'wb') as f:
                    shutil.copyfileobj(conn.connection, f)
            logging.info(f'SQLite database {self.db_name} has been backed up.')
        except Exception as e:
            logging.error(f'Failed to back up SQLite database {self.db_name}. Error: {str(e)}')

    def _create_postgres_backup(self):
        try:
            conn = psycopg2.connect(
                host=self.db_host,
                database=self.db_name,
                user=self.db_user,
                password=self.db_password
            )
            with tarfile.open(os.path.join(self.backup_path, f'{self.db_name}.tar'), 'w:gz') as tar:
                tar.add(self.db_name, arcname=f'{self.db_name}')
            conn.close()
            logging.info(f'Postgres database {self.db_name} has been backed up.')
        except Exception as e:
            logging.error(f'Failed to back up Postgres database {self.db_name}. Error: {str(e)}')

    def _create_mysql_backup(self):
        try:
            conn = mysql.connector.connect(
                host=self.db_host,
                database=self.db_name,
                user=self.db_user,
                password=self.db_password
            )
            with tarfile.open(os.path.join(self.backup_path, f'{self.db_name}.tar'), 'w:gz') as tar:
                tar.add(self.db_name, arcname=f'{self.db_name}')
            conn.close()
            logging.info(f'Mysql database {self.db_name} has been backed up.')
        except Exception as e:
            logging.error(f'Failed to back up Mysql database {self.db_name}. Error: {str(e)}')

    def restore_database(self):
        if self.db_type =='sqlite':
            self._restore_sqlite_database()
        elif self.db_type == 'postgres':
            self._restore_postgres_database()
        elif self.db_type =='mysql':
            self._restore_mysql_database()

    def _restore_sqlite_database(self):
        if os.path.exists(os.path.join(self.restore_path, self.db_name)):
            os.remove(os.path.join(self.restore_path, self.db_name))
        shutil.copy(os.path.join(self.backup_path, f'{self.db_name}.db'), os.path.join(self.restore_path, self.db_name))
