class ContainerDeployer:
    def __init__(self, image_base_url: str, image_name: str, package_path: str):
        self.image_base_url = image_base_url
        self.image_name = image_name
        self.package_path = package_path

    def extract_image(self):
        with tarfile.TarFile(self.package_path, 'r') as tf:
            return tf.extractall()

    def hash_image(self, path: str) -> str:
        image_file = os.path.join(path, f'{self.image_name}.dockerimage')
        if not os.path.exists(image_file):
            return None
        with open(image_file, 'rb') as f:
            image_hash = hashlib.sha256(f.read()).hexdigest()
            return image_file, image_hash

    def create_new_image(self, image_hash: str):
        new_image_name = f"{self.image_name}-${image_hash}"
        new_image_url = f"{self.image_base_url}/{new_image_name}:latest"
        sh.docker.create_container(name=new_image_name, image=self.image_name)
        sh.docker.tag(image=self.image_name, repository=new_image_name, tag='latest')
        sh.docker.push(repository=new_image_name, tags=[new_image_url])
        return new_image_url

    def deploy_new_image(self):
        extracted_files = self.extract_image()
        image_path, image_hash = self.hash_image(self.package_path)
        new_image_url = self.create_new_image(image_hash)
        return new_image_url, image_path, image_hash

    def check_image_deployment_status(self, image_name: str, url: str):
        status = subprocess.run(['docker', 'image', 'inspect', '--format', '"{{.RepoDigests[0] }}"', image_name], capture_output=True, text=True)
        if b'digest:' + url.encode() in status.stdout.encode():
            return True
        return False

class DeploymentManager:
    def __init__(self):
        self.deployers: Dict[str, ContainerDeployer] = {}

    def add_deployer(self, deployer: ContainerDeployer):
        self.deployers[deployer.image_name] = deployer

    def deploy(self, image_name: str, package_path: str, image_base_url: str):
        if image_name not in self.deployers:
            self.deployers[image_name] = ContainerDeployer(image_base_url, image_name, package_path)
        return self.deployers[image_name].deploy_new_image()

# Usage
