def copy_source(src, dest):
    if not os.path.exists(dest):
        os.makedirs(dest)
    for root, dirs, files in os.walk(src):
        for file in files:
            file_path = os.path.join(root, file)
            if os.path.isfile(file_path) and not file.endswith(('.pyc', '.log', '.tmp', '.txt')):
                rel_path = os.path.relpath(file_path, src)
                abs_dest = os.path.join(dest, rel_path)
                os.makedirs(abs_dest, exist_ok=True)
                filename, file_extension = os.path.splitext(file_path)
                if file_extension == '.py':
                    with open(filename + '.py', 'rb') as f, open(abs_dest + file_extension, 'wb') as f_out:
                        f_out.write(f.read())
                elif file_extension in ['.rar', '.zip']:
                    with zipfile.ZipFile(abs_dest + file_extension, 'w') as zf:
                        with open(filename + file_extension, 'rb') as f_in:
                            zf.write(f_in.name, compress_type=zipfile.ZIP_DEFLATED)
                else:
                    shutil.copy2(file_path, abs_dest + file_extension)

def main():
    parser = argparse.ArgumentParser(description='Archive files from a folder, excluding certain file types')
    parser.add_argument('src', help='Source directory')
    parser.add_argument('dest', help='Destination archive')
    args = parser.parse_args()

    if os.path.isdir(args.src):
        if args.dest.lower().endswith('.zip'):
            archiver = zipfile.ZipFile(args.dest, 'w')
            copy_source(args.src, '.')
            for root, dirs, files in os.walk('.'):
                for dir in dirs:
                    if dir!= '.' and dir!= 'build':
                        os.rmdir(os.path.join(root, dir))
            for file in glob.glob('**/*.zip', recursive=True):
                archiver.write(file, compress_type=zipfile.ZIP_DEFLATED)
        elif args.dest.lower().endswith('.rar'):
            archiver = rarfile.RarFile(args.dest, 'w')
            copy_source(args.src, '.')
            for root, dirs, files in os.walk('.'):
                for dir in dirs:
                    if dir!= '.' and dir!= 'build':
                        os.rmdir(os.path.join(root, dir))
            for file in glob.glob('**/*.rar', recursive=True):
                archiver.extract(file)
        else:
            copy_source(args.src, args.dest)
        if os.path.isfile(args.dest) and args.dest.lower().endswith('.rar'):
            rarfile.RarFile(args.dest, 'a')
            rarfile.RarFile(args.dest, 'r', mode='w')
            for file in glob.glob('**/*.rar', recursive=True):
                with open(file, 'rb') as f:
                    archiver.add(f.name, file, 'zip')
                    archiver.close()
        elif args.dest.lower().endswith('.zip'):
            if os.path.isdir('build'):
                shutil.rmtree('build')
