            for file in files:
                file_path = os.path.join(root, file)
                file_size = os.path.getsize(file_path)
                disk_usage[file_path] = file_size
                if file_size >= 100 * 1024 * 1024:  # 100MB
                    print(f"Large file found: {file_path} | Size: {self.format_size(file_size)}")
        return disk_usage

    @staticmethod
    def format_size(size):
        for unit in ['', 'K', 'M', 'G', 'T', 'P', 'E', 'Z']:
            if abs(size) < 1024.0:
                return f"{size:.2f} {unit}B"
            size /= 1024.0
        return f"{size:.2f} YB"

