                print(f"Artifact '{artifact.name}' already exists.")
                return
        if self.artifact_exists(path):
            print(f"Error: '{path}' already exists.")
            return
        self.artifacts[artifact.name] = artifact
        print(f"Artifact '{artifact.name}' added.")

