        with zipfile.ZipFile(archive_path, 'r') as zip_ref:
            zip_ref.extractall(output_dir)

    def rar_extractor(self, archive_path, output_dir):
        self.logger.info('Extracting rar file: %s', archive_path)
        with rarfile.RarFile(archive_path, 'r') as rar_ref:
            rar_ref.extractall(output_dir)

    def tar_extractor(self, archive_path, output_dir):
        self.logger.info('Extracting tar file: %s', archive_path)
        with tarfile.TarFile(archive_path, mode='r') as tar_ref:
            tar_ref.extractall(output_dir)

    def pdf_extractor(self, archive_path, output_dir):
        self.logger.info('Extracting pdf file: %s', archive_path)
        doc = fitz.open(archive_path)
        for i in range(len(doc)):
            page = doc.load_page(i)
            pix = page.get_pixmap(alpha=False)
            pix.save(f'{output_dir}/page_{i}.png')
        doc.close()

    def sevenzip_extractor(self, archive_path, output_dir):
        self.logger.info('Extracting 7z file: %s', archive_path)
        with py7zr.SevenZipFile(archive_path, 'r') as sevenzip_ref:
            sevenzip_ref.extractall(output_dir)

    def extract_file(self, archive_path, output_dir, format):
        if format == 'zip':
            self.zip_extractor(archive_path, output_dir)
        elif format == 'rar':
            self.rar_extractor(archive_path, output_dir)
