def create_temp_dir(suffix=None, prefix='tmp', dir=None):
    """Create a temporary directory.

    Args:
        suffix (str): Suffix of the directory name.
        prefix (str, optional): Prefix of the directory name. Defaults to 'tmp'.
        dir (str, optional): Directory where to create the temporary directory. Defaults to None.

    Returns:
        str: Path to the temporary directory.
