import os
import tarfile
import pickle
import hashlib

class BackupTool:
    def __init__(self, source_dir, backup_dir, archive_format='tar'):
        self.source_dir = source_dir
        self.backup_dir = backup_dir
        self.archive_format = archive_format

    def get_change_list(self):
        """Return a list of files that have changed since the last backup."""
        last_backup = self._get_last_backup_date()
        if last_backup:
            changed_files = []
            for root, dirs, files in os.walk(self.source_dir):
                for file in files:
                    file_path = os.path.join(root, file)
                    if self._file_has_changed(file_path, last_backup):
                        changed_files.append(file_path)
            return changed_files
        else:
            return []

    def _get_last_backup_date(self):
        try:
            with open(os.path.join(self.backup_dir, 'last_backup_date.pkl'), 'rb') as f:
                return pickle.load(f)
        except FileNotFoundError:
            return None

    def _file_has_changed(self, file_path, last_backup_date):
        if last_backup_date is None:
            return True
        mtime = os.path.getmtime(file_path)
        return last_backup_date < mtime

    def backup(self):
        """Create a differential backup of the source directory."""
        if not os.path.exists(self.backup_dir):
            os.makedirs(self.backup_dir)

        changed_files = self.get_change_list()
        if changed_files:
            with tarfile.open(os.path.join(self.backup_dir, 'backup.tar'), 'w', format=self.archive_format, compression=tarfile.Z_DEFAULT_COMPRESSION) as tar:
                for file in changed_files:
                    arcname = os.path.relpath(file, self.source_dir)
