class DiskSpaceAnalyzer:
    def __init__(self, root_dir):
        self.root_dir = root_dir
        self.file_paths = {}
        self.duplicate_files = defaultdict(int)
        self.backup_files = defaultdict(list)

    def traverse_dir(self, path, dir_contents):
        for item in dir_contents:
            item_path = os.path.join(path, item)
            if os.path.isfile(item_path):
                with open(item_path, 'rb') as f:
                    hash_sum = hashlib.md5(f.read()).hexdigest()
                    if hash_sum not in self.file_paths:
                        self.file_paths[hash_sum] = []
                    self.file_paths[hash_sum].append(item_path)
                    self.duplicate_files[item_path] += 1
            elif os.path.isdir(item_path):
                sub_dir_contents = os.listdir(item_path)
                self.traverse_dir(item_path, sub_dir_contents)

    def identify_duplicates_and_backups(self):
        for file_paths in self.file_paths.values():
            if len(file_paths) > 1:
                for file_path in file_paths:
                    self.backup_files[file_path].extend(
                        [fp for fp in file_paths if fp!= file_path]
                    )

    def print_duplicate_and_backup_files(self):
        for file_path, count in self.duplicate_files.items():
            print(f"File: {file_path}, Count: {count}")
        for file_path, backup_files in self.backup_files.items():
            print(f"File: {file_path}, Backup Files: {', '.join(backup_files)}")

    def delete_redundant_files(self):
