import zipfile
import gzip
import io

class PackageUtil:
    @staticmethod
    def create_archive(src_dir, file_path, format='tar.gz'):
        if format == 'tar.gz':
            with tarfile.open(file_path, 'w:gz') as tar:
                tar.add(src_dir, arcname=os.path.basename(src_dir))
            return True
        elif format == 'zip':
            with zipfile.ZipFile(file_path, 'w') as zip_file:
                for root, dirs, files in os.walk(src_dir):
                    for file in files:
                        file_path = os.path.join(root, file)
                        arcname = os.path.relpath(file_path, src_dir)  # relative path
                        zip_file.write(file_path, arcname)
            return True
        else:
            return False

    @staticmethod
    def extract_archive(file_path, dst_dir, format='tar.gz'):
        if format == 'tar.gz':
            with tarfile.open(file_path, 'r:gz') as tar:
                tar.extractall(dst_dir)
        elif format == 'zip':
            with zipfile.ZipFile(file_path, 'r') as zip_file:
                zip_file.extractall(dst_dir)
        return True

def main():
    # source directory
    src_dir ='source_dir'
    # archive file path
    file_path = 'package.tar.gz'
    # destination directory
    dst_dir = 'destination_dir'

    if PackageUtil.create_archive(src_dir, file_path):
        print('Archive creation success')
        if PackageUtil.extract_archive(file_path, dst_dir):
            print('Archive extraction success')
        else:
            print('Archive extraction failed')
    else:
        print('Archive creation failed')

if __name__ == '__main__':
    main()
