import os
import argparse
import zipfile
import tarfile
import tar

class ArtifactDeployer:
    def __init__(self, artifact_path, deployment_dir):
        self.artifact_path = artifact_path
        self.deployment_dir = deployment_dir

    def extract_zip(self):
        if not os.path.exists(self.deployment_dir):
            os.makedirs(self.deployment_dir)

        with zipfile.ZipFile(self.artifact_path, 'r') as zip_ref:
            zip_ref.extractall(self.deployment_dir)

    def extract_tar(self):
        if not os.path.exists(self.deployment_dir):
            os.makedirs(self.deployment_dir)

        with tarfile.TarFile(self.artifact_path) as tar_ref:
            tar_ref.extractall(self.deployment_dir)

    def deploy_container_image(self):
        if not self.artifact_path.endswith('.zip'):
            self.extract_tar()
        elif self.artifact_path.endswith('.zip'):
            self.extract_zip()

        # Assuming container image is a tar file inside the extracted archive
        for root, dirs, files in os.walk(self.deployment_dir):
            for file in files:
                if file.endswith('.tar'):
                    container_path = os.path.join(root, file)
                    subprocess.run(['docker load', container_path])

        if os.path.exists(self.deployment_dir):
            print("Container image deployed successfully.")
            os.system('docker images')
        else:
            print("No container image found in the artifact.")

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Deploy container image from artifact")
    parser.add_argument("-a", "--artifact", help="Path to the compressed artifact file")
    parser.add_argument("-d", "--deployment", help="Directory to extract the artifact")
    args = parser.parse_args()

    if not args.artifact or not args.deployment:
        parser.error('Both --artifact and --deployment are required')

    deployer = ArtifactDeployer(args.artifact, args.deployment)
    deployer.deploy_container_image()
