class DiskZipUtility:
    def __init__(self, src_dir, dst_dir):
        self.src_dir = src_dir
        self.dst_dir = dst_dir

    def list_zip_files(self):
        return [item for item in os.listdir(self.src_dir) if item.endswith('.zip')]

    def extract_zip(self, zip_file):
        with zipfile.ZipFile(f'{self.src_dir}/{zip_file}', 'r') as zip_ref:
            zip_ref.extractall(self.dst_dir)

    def main(self):
        zip_files = self.list_zip_files()
        for zip_file in zip_files:
            print(f'Extracting {zip_file}...')
            self.extract_zip(zip_file)
            print(f'Extracted {zip_file} successfully.')

def parse_args():
    parser = argparse.ArgumentParser(description='Extracts and copies data from old Zip disks to modern storage media')
    parser.add_argument('-s', '--src', required=True, help='Source directory containing Zip files')
    parser.add_argument('-d', '--dst', required=True, help='Destination directory to copy extracted files to')
    return parser.parse_args()

def main():
    args = parse_args()
    if not os.path.exists(args.src):
        print('Source directory does not exist')
        sys.exit(1)

    if not os.path.exists(args.dst):
        os.makedirs(args.dst)

