import os
import shutil
import pathlib

class DirectoryArchiver:
    def __init__(self, root_dir, pattern=None, destination_dir=None, archive_format='.zip'):
        self.root_dir = pathlib.Path(root_dir)
        self.pattern = pattern
        self.destination_dir = pathlib.Path(destination_dir) if destination_dir else pathlib.Path('./archive')
        self.archive_format = archive_format

    def _get_files(self, directory):
        if self.pattern is None:
            return list(directory.glob('*'))
        else:
            return [file for file in directory.glob('*') if self.pattern.match(file.name)]

    def _create_archive(self, file):
        return pathlib.Path(f'{file.parent.name}_{file.name}.{self.archive_format}')

    def _copy_file(self, source, destination):
        if source.suffix == '.directory':
            # Do not copy the directory itself
            if not os.path.exists(destination.parent):
                os.makedirs(destination.parent)
            for file in os.listdir(source):
                shutil.copy(os.path.join(source, file), os.path.join(destination.parent, file))
        else:
            shutil.copy2(source, destination)

    def archive(self):
        for directory, _, files in os.walk(self.root_dir):
            for file in self._get_files(Path(directory)):
                if file.suffix not in ['.directory']:
                    archive_file = self._create_archive(file)
                    destination = self.destination_dir.joinpath(archive_file)
                    if not os.path.exists(destination):
                        self._copy_file(file, destination)
                    else:
                        print(f'Archive "{destination.name}" already exists.')
                        choice = input('Do you want to overwrite it? (y/n): ')
                        if choice.lower() == 'y':
                            os.remove(destination)
                            self._copy_file(file, destination)

if __name__ == '__main__':
    archiver = DirectoryArchiver(
        root_dir='/path/to/your/directory',
        pattern=None,  # None for no filtering, otherwise: a regular expression object
        destination_dir=None,  # None for default location, otherwise: path to the destination directory
        archive_format='.zip'  # Default archive format:.zip
    )
    archiver.archive()
