class TarballNavigator:
    def __init__(self, tar_file):
        self.tar_file = tar_file
        with tarfile.open(tar_file, 'r') as tar:
            self.contents = tar.getnames()

    def walk_contents(self):
        contents = set()
        for root, dirs, files in os.walk('.'):
            for f in files:
                contents.add(os.path.join(root, f))
        return list(contents)

    def get_contents(self):
        if self.tar_file:
            try:
                return self.contents
            except AttributeError:
                return self.walk_contents()
        else:
            return []

    def list_directory(self):
        if not self.tar_file:
            contents = self.get_contents()
        else:
            try:
                tar = tarfile.open(self.tar_file, 'r')
                contents = tar.getnames()
                tar.close()
            except tarfile.TarError:
                return "Invalid tarball"
