        tar.extractall(extract_path)

def extract_zip_file(zip_file_path, extract_path):
    with zipfile.ZipFile(zip_file_path, 'r') as zip_ref:
        zip_ref.extractall(extract_path)

def extract_rar_file(rar_file_path, extract_path):
    with rarfile.RarFile(rar_file_path, 'r') as rar_ref:
        rar_ref.extractall(extract_path)

def extract_file_from_archive(file_path, extract_path, archive_type):
    if archive_type == 'tar':
        extract_tar_file(file_path, extract_path)
    elif archive_type == 'zip':
        extract_zip_file(file_path, extract_path)
    elif archive_type == 'rar':
        extract_rar_file(file_path, extract_path)
    else:
        print("Unsupported archive type")

def extract_all(file_paths, extract_path):
    for file_path in file_paths:
        file_name = os.path.basename(file_path)
        extract_file_from_archive(file_path, os.path.join(extract_path, file_name), file_name.split('.')[0])

