    file_paths = ['path_to_your_tar_file.tar.gz', 'path_to_your_zip_file.zip', 'path_to_your_rar_file.rar']
    extract_path = 'extracted_files'
    if not os.path.exists(extract_path):
        os.makedirs(extract_path)

