import os
import stat

class Renamer:
    def __init__(self, directory, pattern, new_name, permissions=None):
        self.directory = directory
        self.pattern = pattern
        self.new_name = new_name
        self.permissions = permissions if permissions else None

    def _get_pattern_func(self):
        if self.pattern.startswith('$'):
            return lambda x: self.pattern.replace('$name', os.path.basename(x))
        elif self.pattern.startswith('^'):
            return lambda x: self.pattern.replace('^', '')
        else:
            return lambda x: self.pattern

    def _apply_permissions(self, file):
        if self.permissions:
            os.chmod(file, self.permissions)

    def rename_files(self):
        for root, dirs, files in os.walk(self.directory):
            for file in files:
                original_file = os.path.join(root, file)
                new_file = os.path.join(root, self._get_pattern_func()(original_file))
                os.rename(original_file, new_file)
                self._apply_permissions(new_file)
                print(f'Renamed {original_file} to {new_file}')

def main():
    import argparse
    parser = argparse.ArgumentParser(description='Bulk renamer with permissions')
    parser.add_argument('-d', '--directory', required=True, help='Directory to rename files in')
    parser.add_argument('-p', '--pattern', required=True, help='Renaming pattern')
    parser.add_argument('-n', '--new-name', required=True, help='New name')
    parser.add_argument('-u', '--permissions', type=int, help='Permissions (octal value)')
    parser.add_argument('-f', '--force', action='store_true', help='Force overwrite')
    args = parser.parse_args()

    if not os.path.exists(args.directory):
        print('Directory does not exist')
        return

    if not os.access(args.directory, os.W_OK):
        print('Directory is not writable')
        return

    renamer = Renamer(args.directory, args.pattern, args.new_name, args.permissions)
    if not args.force and os.path.exists(renamer.directory):
        print('Please specify -f (force overwrite) flag if you want to overwrite existing files')
        return

    renamer.rename_files()

if __name__ == '__main__':
    main()
