    parser.add_argument('source', type=str, help='path to source directory or file')
    parser.add_argument('dest', type=str, help='path to destination directory')
    args = parser.parse_args()

    backup_util = BackupUtility(args.source, args.dest)

    if os.path.isdir(args.source):
        backup_util.copy_dir()
    else:
        file_name = args.source
        backup_util.copy_file(file_name)

