def check_coding_style(tar_file):
    with tarfile.open(tar_file, 'r:gz') as tar:
        for member in tar.getmembers():
            if member.isdir():
                with tar.extractfile(member) as member_file:
                    try:
                        lines = member_file.read().decode('utf-8').splitlines()
                        if any('lambda' in line for line in lines) or any('eval(' in line or line.startswith(('print(', 'exec(')) for line in lines):
                            print(f"Code smell detected in {member.path}: Lambda or eval function found")
                        if any('magic number' in line.lower() for line in lines):
