        self.files = {}

    def walk_dir(self):
        for root, dirs, files in os.walk(self.root_dir):
            for file in files:
                file_path = os.path.join(root, file)
                self.files[file_path] = open(file_path, 'rb').read()

    def hash_files(self):
        file_hashes = {}
        for file_path, file_data in self.files.items():
            file_hash = hashlib.md5(file_data).hexdigest()
            if file_hash in file_hashes:
                file_hashes[file_hash].append(file_path)
            else:
                file_hashes[file_hash] = [file_path]
        return file_hashes

    def find_duplicates(self):
        hashes = self.hash_files()
        duplicates = {hash: [file for file in files if self.size_check(file)] for hash, files in hashes.items() if len(files) > 1}
        return duplicates

    def size_check(self, file_path):
        return os.path.getsize(file_path) == os.path.getsize(open(file_path, 'rb').read(1024)) * (os.path.getsize(file_path) // 1024)

    def print_duplicates(self, duplicates):
        for hash, files in duplicates.items():
