from datetime import datetime

class ArtifactManager:
    def __init__(self, root_directory):
        self.root_directory = root_directory
        self.artifacts = {}

    def add_artifact(self, name, artifact_file_path):
        if name not in self.artifacts:
            self.artifacts[name] = {'file_path': artifact_file_path, 'timestamp': datetime.now()}
        else:
            raise ValueError(f"Artifact '{name}' already exists")

    def delete_artifact(self, name):
        if name in self.artifacts:
            os.remove(self.artifacts.pop(name)['file_path'])
        else:
            raise ValueError(f"Artifact '{name}' does not exist")

    def list_artifacts(self):
        return self.artifacts.keys()

    def compress_artifact(self, name):
        artifact = self.artifacts.get(name)
        if artifact:
            with tarfile.open(f'{name}.tar', 'w:gz') as tar:
                tar.add(artifact['file_path'])
            os.remove(artifact['file_path'])
            artifact['file_path'] = f'{name}.tar.gz'

    def decompress_artifact(self, name):
        artifact = self.artifacts.get(name)
        if artifact and artifact.get('compressed'):
            with tarfile.open(artifact['file_path'], 'r:gz') as tar:
                tar.extractall()
            os.remove(artifact['file_path'])
            artifact['file_path'] = tar.getnames()[0]

class DistributionManager:
    def __init__(self, root_directory):
        self.root_directory = root_directory
        self.distributions = {}

    def add_distribution(self, name, artifact_name):
        if name not in self.distributions:
            self.distributions[name] = { 'artifact_name': artifact_name, 'timestamp': datetime.now() }
        else:
            raise ValueError(f"Distribution '{name}' already exists")

    def list_distributions(self):
        return self.distributions.keys()

    def get_artifact_for_distribution(self, name):
        return self.distributions.get(name, {}).get('artifact_name')

class Pipeline:
    def __init__(self, artifact_manager: ArtifactManager, distribution_manager: DistributionManager):
        self.artifact_manager = artifact_manager
        self.distribution_manager = distribution_manager

    def create_distribution(self, distribution_name, artifact_name):
        self.artifact_manager.add_artifact(artifact_name, f'{self.artifact_manager.root_directory}/{artifact_name}')
        self.artifact_manager.compress_artifact(artifact_name)
        self.distribution_manager.add_distribution(distribution_name, artifact_name)

