            self._check_complexity(node, child)

    def _check_complexity(self, parent, child):
        nesting = len(list(ast.walk(parent)) - 1)
        complexity = self._calculate_complexity(child)
        length = len(child.body)

        if self._is_complex(child) and (nesting > self.max_nesting or complexity > self.max_complexity or length > self.max_length):
            self.report.append({
                'filename': parent.id,
                'name': child.id,
                'type': type(child).__name__,
                'line': child.lineno,
                'nesting': nesting,
                'complexity': complexity,
                'length': length
            })

