                        zip_file.write(file_path, os.path.relpath(file_path, source_dir))
        elif self.archive_format == 'tar':
            with tarfile.open(self._get_archive_path(archive_name), 'w', compression=self.get_compression_type(compression_level)) as tar_file:
                tar_file.add(source_dir, arcname=os.path.basename(source_dir))
        else:
            raise ValueError('Unsupported archive format')

    def _get_archive_path(self, archive_name):
        return os.path.join(self.backup_dir, f'{archive_name}.{self.archive_format}')

    def get_compression_type(self, compression_level):
        compression_types = {
            6: zipfile.ZIP_DEFLATED,
            7: zipfile.ZIP_LZMA,
            # Other compression types can be added here
        }
        return compression_types.get(compression_level, zipfile.ZIP_DEFLATED)

