class ModManager:
    def __init__(self, mod_directory):
        self.mod_directory = mod_directory

    def download_mod(self, name, url):
        response = requests.get(url)
        if response.status_code == 200:
            with open(os.path.join(self.mod_directory, name), 'wb') as f:
                f.write(response.content)
            return True
        else:
            print(f"Failed to download {name}")
            return False

    def extract_tar(self, filename):
        try:
            tar = tarfile.open(filename, 'r:gz')
            tar.extractall(self.mod_directory)
            tar.close()
            return True
        except Exception as e:
            print(f"Failed to extract {filename}: {str(e)}")
            return False

    def install_mod(self, name, filename):
        if self.download_mod(name, filename):
            if self.extract_tar(os.path.join(self.mod_directory, name)):
                return True
        return False

    def get_mod_list(self):
        return [f for f in os.listdir(self.mod_directory) if f.endswith('.tar.gz')]

    def uninstall_mod(self, name):
        try:
            shutil.rmtree(os.path.join(self.mod_directory, name))
            return True
        except Exception as e:
            print(f"Failed to uninstall {name}: {str(e)}")
            return False

    def list_installed_mods(self):
        return [f for f in os.listdir(self.mod_directory) if os.path.isdir(os.path.join(self.mod_directory, f)) and not f.endswith('.tar.gz')]

    def create_mod_json(self):
        mods = {}
        for mod in self.list_installed_mods():
            mods[mod] = f"Downloaded from {self.get_mod_list()[self.list_installed_mods().index(mod)]}"
        with open(os.path.join(self.mod_directory,'mods.json'), 'w') as f:
            json.dump(mods, f)

    def display_mod_info(self):
        if os.path.exists(os.path.join(self.mod_directory,'mods.json')):
            with open(os.path.join(self.mod_directory,'mods.json'), 'r') as f:
                print(json.load(f))

def main():
    mod_manager = ModManager('/path/to/mods')
    print("Available mods:")
