from dwg import read_dxf

def get_entities(file_path):
    """Read the DXF file and extract entities."""
    try:
        with open(file_path, 'rb') as f:
            model = read_dxf(f)
            return model.entities
    except Exception as e:
        print(f"Error: {e}")

def get_line_length(line):
    """Calculate the length of a LINE entity."""
    try:
        if line.dxftype() == 'LINE':
            end1 = line.get_endpoint(0)
            end2 = line.get_endpoint(1)
            return ((end2[0] - end1[0])**2 + (end2[1] - end1[1])**2)**0.5
        else:
            return None
    except Exception as e:
        print(f"Error: {e}")
        return None

def get_polygon_area(polygon):
    """Calculate the area of a POLYLINE entity."""
    try:
        if polygon.dxftype() == 'POLYLINE' and len(polygon.verts) >= 3:
            xys = [point[0] for point in polygon.verts]
            if xys:
                xys = [tuple(list(xys) + [0]) for xys in xys]
                length, result, _ = polypolygon_area(xys)
                return result
            else:
                return None
        else:
            return None
    except Exception as e:
        print(f"Error: {e}")
        return None

def polypolygon_area(xys):
    """Area of a polygon given a list of (x, y) coordinates."""
    n = len(xys)
    area = 0.0
    for i in range(n):
        j = (i + 1) % n
        area += xys[i][0] * xys[j][1]
        area -= xys[j][0] * xys[i][1]
    area = abs(area) / 2.0
    return 2*n, area, (area, xys)

def main():
    file_path = input("Enter the path to the DXF file: ")
    entities = get_entities(file_path)
    for entity in entities:
        if entity.dxftype() == 'LINE':
            print(f"Line {entity.object_name} has length {get_line_length(entity)}")
        elif entity.dxftype() == 'POLYLINE':
            print(f"Polygon with {len(entity.verts)} points has area {get_polygon_area(entity)}")

if __name__ == "__main__":
