import json

class TemplateRenderer:
    def __init__(self, template: str):
        self.template = template

    def render(self, data: dict):
        if not isinstance(self.template, str):
            raise ValueError("Template must be a string")
        if not isinstance(data, dict):
            raise ValueError("Data must be a dictionary")

        rendered = self.template
        for key, value in data.items():
            rendered = rendered.replace(f"{{{key}}}", str(value))

        return rendered


class JinjaTemplateRenderer(TemplateRenderer):
    def __init__(self, template: str):
        super().__init__(template)

    def render(self, data: dict):
        rendered = super().render(data)
        return rendered.replace('{{', "{").replace('}}', '}')


class JsonTemplateRenderer(TemplateRenderer):
    def __init__(self, template: str):
        super().__init__(template)

    def render(self, data: dict):
        rendered = super().render(data)
        # For each object or array, replace it with its JSON representation
        self._replace_json(rendered, data)
        return rendered

    def _replace_json(self, rendered: str, data: dict):
        for key, value in data.items():
            if isinstance(value, dict):
                rendered = rendered.replace(f"{{{key}", '{""")}')
                self._replace_json(rendered, value)
                rendered = rendered.replace("}}}", ',"":'+ json.dumps(value) + '}}}')
            elif isinstance(value, list):
                rendered = rendered.replace(f"{{{key}", '[')
                self._render_list(rendered, value)
                rendered = rendered.replace("}}]", ']}')
            else:
                rendered = rendered.replace(f"{{{key}}}", str(value))


    def _render_list(self, rendered: str, data: list):
        index = 0
        for item in data:
            self._render_json_sub_element(rendered, item, index)
            index += 1


    def _render_json_sub_element(self, rendered: str, data: dict or str or int, index: int):
        if isinstance(data, str):
            rendered = rendered.replace('[', '').replace(']', '')
            rendered = rendered.replace("{%s}}" % index, json.dumps(data))
        elif isinstance(data, int):
            rendered = rendered.replace('[', '').replace(']', '')
            rendered = rendered.replace("{%s}}" % index, str(data))
        elif isinstance(data, dict):
            rendered = rendered.replace('[', '').replace(']', '')
            self._replace_json(rendered, data)
            rendered = rendered.replace("{%s}}" % index, json.dumps(data))


