from jinja2 import Environment, BaseLoader, TemplateNotFound

class Jinja2FileLoader(BaseLoader):
    def __init__(self, searchpath):
        self.searchpath = searchpath

    def get_source(self, environment, template):
        try:
            with open(os.path.join(self.searchpath, template), 'r') as fp:
                content = fp.read()
            return content, template, None
        except EnvironmentError:
            raise TemplateNotFound(template)

class CodeGenerator:
    def __init__(self, templates_dir, output_dir):
        self.jinja_env = Environment(loader=Jinja2FileLoader(templates_dir))
        self.output_dir = output_dir

