                print(f"File {filename} does not exist in output directory.")
                return
            filepath = os.path.join(self.output_dir, filename)
            try:
                os.chmod(filepath, perms)
                print(f"Permission set for {filename} to {perms}")
            except OSError as e:
                print(f"Failed to set permissions for {filename}: {e}")

