import os
import shutil
import stat
import getpass
import grp
import pwd

def copy_files(src_dir, dst_dir, permissions=None):
    if not os.path.exists(src_dir):
        raise ValueError(f"Source directory '{src_dir}' not found.")
    if not os.path.exists(dst_dir):
        os.makedirs(dst_dir)

    for filename in os.listdir(src_dir):
        src_file_path = os.path.join(src_dir, filename)
        dst_file_path = os.path.join(dst_dir, filename)

        if os.path.isfile(src_file_path):
            if permissions is None:
                shutil.copy2(src_file_path, dst_file_path)
            else:
                st = os.stat(src_file_path)
                if isinstance(permissions, int):
                    shutil.copymode(dst_file_path, st.st_mode & ~stat.S_IFMT)
                    os.chmod(dst_file_path, stat.S_IMODE(permissions))
                elif isinstance(permissions, str):
                    perm_map = {
                        'rwx': stat.S_IRWXU, 'rw-': stat.S_IWUSR, 'r--': stat.S_IROTH,
                        'r-x': stat.S_IXUSR, '-w-': stat.S_IWGRP, '--x': stat.S_IXGRP,
                        '-rw': stat.S_IRUSR, '--w': stat.S_IWOTH, '-x-': stat.S_IXOTH
                    }
                    permissions = permissions[::-1]
                    ownership = os.stat(src_file_path).st_uid
                    permissions = 0
                    for i in range(len(permissions)):
                        permissions |= perm_map.get(permissions[i], 0)
                    os.chown(dst_file_path, ownership, -1)
                    shutil.copymode(dst_file_path, permissions)
        elif os.path.isdir(src_file_path):
            copy_files(src_file_path, dst_file_path, permissions)

def main():
    username = getpass.getuser()
    password = getpass.getpass("Enter password for user {}: ".format(username))
    groups = [g.gr_name for g in grp.getgrall() if username in g.gr_mem]
    pw = pwd.pwd.getpwnam(username)
    print("User's groups: ", groups)
    src_dir = input("Enter source directory: ")
    dst_dir = input("Enter destination directory: ")
    permissions = input("Enter file permissions (e.g., rw-r--r-- for 644 or rwxr-x-r-x for 755), or leave blank for default permissions: ")
    if permissions:
        permissions = ''.join(filter(str.isalpha, permissions))  # Remove any digits
        if permissions in ['rw-r--r--', 'rwxr-xr-x']:
            permissions = ''.join([ord(p) - 87 for p in permissions])
        else:
            print("Invalid permission string. Using default permissions.")
            permissions = None

    try:
        copy_files(src_dir, dst_dir, permissions)
        print("Files copied successfully.")
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
