        self.search_button.pack()
        self.categories = {}
        self.conn = sqlite3.connect('todo.db')
        self.cursor = self.conn.cursor()
        self.cursor.execute('''CREATE TABLE IF NOT EXISTS categories
                            (category text, filename text, line_number integer)''')
        self.conn.commit()
        self.root.mainloop()

    def create_dir_if_not_exists(self, dirpath):
        if not os.path.exists(dirpath):
            os.mkdir(dirpath)

    def browse_directory(self):
        self.entry.delete(0, tk.END)
        self.entry.insert(0, filedialog.askdirectory())

    def search_todo_comments(self):
        directory = self.entry.get()
        if not directory:
            return
        self.categories = {}
        for root, dirs, files in os.walk(directory):
            for file in files:
                if file.endswith('.py'):
                    file_path = os.path.join(root, file)
                    with open(file_path, 'r') as f:
                        for line, line_no in enumerate(f, start=1):
                            if re.search(r'# TODO', line):
                                category = simpledialog.askstring('Category', 'Category for'+ file_path)
                                if category:
                                    self.add_todo(file_path, line_no, category)
        self.listbox.delete(0, tk.END)
        for category in self.categories:
            self.listbox.insert(tk.END, f'{category}: {len(self.categories[category])}')

    def add_todo(self, path, line, category):
        if category not in self.categories:
            self.categories[category] = []
        self.categories[category].append((path, line))
        self.cursor.execute('''INSERT INTO categories (category, filename, line_number) VALUES (?,?,?)''',
                           (category, os.path.basename(path), line))
        self.conn.commit()

if __name__ == '__main__':
    create_dir_if_not_exists('data')
    create_dir_if_not_exists('logs')
    app = ToDoCategorizer()
