class WebArchive:
    def __init__(self, domain, subdomains_to_exclude):
        self.domain = domain
        self.subdomains_to_exclude = subdomains_to_exclude

    def exclude_subdomain(self, url):
        for subdomain in self.subdomains_to_exclude:
            if subdomain in url:
                return True
        return False

    def get_html(self, url):
        try:
            response = requests.get(url)
            if response.status_code == 200:
                return response.text
            else:
                logging.error(f"Failed to retrieve HTML from {url}. Status code: {response.status_code}")
                return None
        except Exception as e:
            logging.error(f"Failed to retrieve HTML from {url}: {e}")
            return None

    def take_snapshot(self, url):
        html = self.get_html(url)
        if html is not None:
            soup = BeautifulSoup(html, "html.parser")
            for script in soup(["script", "style"]):
                script.decompose()
            filename = f"{url.split('/')[-1]}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.html"
            with open(filename, "w") as f:
                f.write(soup.prettify())
            logging.info(f"HTML saved to {filename}")

    def pdf_snapshot(self, url):
        html = self.get_html(url)
        if html is not None:
            filename = f"{url.split('/')[-1]}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.pdf"
            options = {
                'page-size': 'Letter',
               'margin-top': '0.75in',
               'margin-right': '0.75in',
               'margin-bottom': '0.75in',
               'margin-left': '0.75in',
                'encoding': "UTF-8",
                'quiet': ''
            }
            rendered = pdfkit.from_string(html, False, options=options)
            with open(filename, 'wb') as f:
                f.write(rendered)
            logging.info(f"PDF saved to {filename}")

    def snap_all_pages(self, url):
        base_url = f"{self.domain}/"
        if not self.exclude_subdomain(url):
            response = requests.get(url)
            if response.status_code == 200:
                soup = BeautifulSoup(response.text, "html.parser")
                for link in soup.find_all('a'):
                    href = link.get('href')
                    absolute_url = urlparse(href).geturl()
                    if not self.exclude_subdomain(absolute_url):
                        relative_url = os.path.relpath(absolute_url, base_url)
                        if relative_url not in ["../", "./"]:
