class ModDownloader:
    def __init__(self, mod_name, download_dir):
        self.mod_name = mod_name
        self.download_dir = download_dir
        self.mod_data = self.get_mod_data()

    def get_mod_data(self):
        try:
            response = requests.get(f'https://mods.example.com/api/v1/mods/{self.mod_name}')
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            print(f"Error fetching mod data: {e}")
            return None

    def download_mod(self):
        if self.mod_data is not None:
            if 'author' in self.mod_data and 'download_url' in self.mod_data:
                author = self.mod_data['author']
                download_url = self.mod_data['download_url']

                filename = os.path.basename(download_url)
                download_path = os.path.join(self.download_dir, filename)

                print(f"Downloading {author} - {self.mod_name} version {self.mod_data['version']}")

                response = requests.get(download_url, stream=True)
                total_size = int(response.headers.get('content-length', 0))
                downloaded = 0
                with open(download_path, 'wb') as file:
                    for chunk in response.iter_content(chunk_size=8192):
                        if chunk: # filter out keep-alive new chunks
                            file.write(chunk)
                        downloaded += len(chunk)
                        print(f"\rDownloading... {downloaded} bytes out of {total_size} bytes", end='')

                print(f"\nDownload complete! ({datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
            else:
                print("Download URL not found.")
        else:
            print("No mod data available.")

    def extract_mod(self):
        if os.path.exists(os.path.join(self.download_dir, f"{self.mod_name}.zip")):
            zip_ref = zipfile.ZipFile(os.path.join(self.download_dir, f"{self.mod_name}.zip"), 'r')
            zip_ref.extractall(self.download_dir)
            zip_ref.close()
            os.remove(os.path.join(self.download_dir, f"{self.mod_name}.zip"))
            print(f"Mod extracted to {self.download_dir}")
        else:
            print(f"No.zip file found in download directory for {self.mod_name}")

    def install_mod(self):
        self.download_mod()
        self.extract_mod()
        print("Mod installed successfully.")

def get_mod_list():
