                command = f'pyinstaller -n {self.project_name} -i src/{filename} src/{filename}'
                subprocess.run(command, shell=True, cwd=self.build_dir)
                executable_path = f'{self.project_name}/{filename_without_ext}.exe'
                shutil.move(f'{self.project_name}/dist/{filename_without_ext}.exe', executable_path)

def run_build(project_name, source_dir, build_dir, requirements):
