import os
import zipfile
import shutil
import tempfile
from pip import get_distribution, DistributionNotFound

def get_classpath_classifiers():
    classifiers = []
    for dist in get_distribution('jpackage').parsed_requirements:
        classifier = dist['classifier']
        if 'jar' in classifier.lower():
            classifiers.append(classifier)
    return classifiers

def get_dependencies(classifiers):
    dependencies = {}
    for classifier in classifiers:
        packaging = classifier.split('providedBy=')[1]
        packaging = packaging.split(' ')[0]
        dependencies[packaging] = 'jar'
    return dependencies

def get_jar_files(dependencies, packaging_dir):
    jars = []
    for file in os.listdir(packaging_dir):
        if file.endswith('.jar'):
            name = file.split('.')[0]
            name = name.split('/')[-1]
            if name in dependencies:
                jars.append(os.path.join(packaging_dir, file))
    return jars

def create_zip_file(dependencies, jars, output_filename):
    with tempfile.TemporaryDirectory() as tmp_dir:
        for jar in jars:
            shutil.copy2(jar, tmp_dir)
        with zipfile.ZipFile(output_filename, 'w') as zip_file:
            for file in os.listdir(tmp_dir):
                zip_file.write(os.path.join(tmp_dir, file))

if __name__ == "__main__":
    output_filename = 'dependencies.zip'
    classifiers = get_classpath_classifiers()
    dependencies = get_dependencies(classifiers)
    packaging_dir = '/path/to/packaging/files'
    jars = get_jar_files(dependencies, packaging_dir)
    create_zip_file(dependencies, jars, output_filename)
