from __future__ import annotations
from typing import Dict, List
import os
import tarfile
import hashlib
import json
from pathlib import Path

class Artifact:
    def __init__(self, name: str, version: str, metadata: Dict[str, str]):
        self.name = name
        self.version = version
        self.metadata = metadata

class CDTool:
    def __init__(self, root_dir: str):
        self.root_dir = Path(root_dir)
        self.artifacts: Dict[str, Artifact] = {}

    def create_artifact(self, name: str, version: str, metadata: Dict[str, str]):
        artifact = Artifact(name, version, metadata)
        self.artifacts[name] = artifact

    def get_artifact(self, name: str) -> Artifact | None:
        return self.artifacts.get(name)

    def remove_artifact(self, name: str):
        if name in self.artifacts:
            del self.artifacts[name]

    def update_artifact(self, name: str, version: str, metadata: Dict[str, str]):
        if name in self.artifacts:
            self.artifacts[name].version = version
            self.artifacts[name].metadata.update(metadata)
        else:
            self.create_artifact(name, version, metadata)

class Tarball:
    def __init__(self, filename: str):
        self.filename = filename
        self.contents: List[str] = []
        self.md5sum: str = ""

    def add_file(self, path: str, contents: str):
        self.contents.append((path, contents))

    def calculate_checksum(self):
        with open(self.filename, 'w') as f:
            for path, contents in self.contents:
                f.write(f"{path}\n{contents}\n")
        with open(self.filename, 'rb') as f:
            current_md5 = hashlib.md5(f.read()).hexdigest()
        os.remove(self.filename)
        return current_md5

class Pipeline:
    def __init__(self, root_dir: str):
        self.root_dir = Path(root_dir)
        self.tarballs: Dict[str, Tarball] = {}
        self.cd_tool = CDTool(root_dir)

    def create_tarball(self, artifact_name: str, tarball_name: str):
        tarball = Tarball(str(self.root_dir / tarball_name))
        self.tarballs[tarball_name] = tarball

    def add_file(self, artifact_name: str, tarball_name: str, path: str, contents: str):
        if artifact_name in self.cd_tool.artifacts and tarball_name in self.tarballs:
            self.tarballs[tarball_name].add_file(path, contents)
        else:
            raise ValueError("Artifact or Tarball does not exist")

    def build(self):
        for tarball_name, tarball in self.tarballs.items():
            contents_str = ""
            for path, contents in tarball.contents:
                contents_str += f"{path}\n{contents}\n"
            self.tarballs[tarball_name].contents = []
            with open(str(Path(self.root_dir) / tarball.filename), 'w') as f:
                f.write(contents_str)
            tarball.md5sum = self.tarballs[tarball_name].calculate_checksum()

    def publish(self, artifact_name: str, tarball_name: str):
        artifact = self.cd_tool.get_artifact(artifact_name)
        if artifact and tarball_name in self.tarballs:
            artifact.metadata['md5sum'] = self.tarballs[tarball_name].md5sum
            self.build()  # rebuild tarball
        else:
            raise ValueError("Artifact or Tarball does not exist")

