class FileRenamer:
    def __init__(self, dry_run=False):
        self.dry_run = dry_run

    def rename_file(self, src, dest):
        if not self.dry_run:
            os.rename(src, dest)
            print(f"Renamed '{src}' to '{dest}'")

    def rename_files(self, path):
        for root, dirs, files in os.walk(path):
            for f in files:
                src = os.path.join(root, f)
                name, ext = os.path.splitext(f)

                # options:
                # 1. lowercase
                # 2. uppercase
                # 3. camel case
                # 4. underscore separated
                def to_lowercase(s):
                    return s.lower()

                def to_uppercase(s):
                    return s.upper()

                def to_camel_case(s):
                    return re.sub(r'\s+|-|_', '', s).capitalize()

                def to_underscore(s):
                    return re.sub(r'\s+', '_', s).lower()

                # prompt user for the desired option
                print("Available options:")
                print("1. Lowercase")
                print("2. Uppercase")
                print("3. Camel Case")
                print("4. Underscore Separated")
                option = input("Choose the desired renamer option: ")

                if option == "1":
                    new_name = to_lowercase(name) + ext
                elif option == "2":
                    new_name = to_uppercase(name) + ext
                elif option == "3":
                    new_name = to_camel_case(name) + ext
                elif option == "4":
                    new_name = to_underscore(name) + ext
                else:
                    print("Invalid option, using original filename")
                    new_name = f + '.' + ext

                dest = os.path.join(root, new_name)
                self.rename_file(src, dest)

    def main(self, path):
        print(f"Starting file renamer on path: {path}")
        self.rename_files(path)
        print("File renaming complete.")

def main():
