    def cleanup(self, repo_name: str):
        """Remove the repository directory and its contents."""
        try:
            repo_dir = self.root_dir / repo_name
            if repo_dir.exists():
                shutil.rmtree(repo_dir)
                print(f"Repo {repo_dir} cleaned up.")
            else:
                print(f"No repository found at {repo_dir}.")
        except Exception as e:
            print(f"Failed to cleanup repository: {e}")


