class ContinuousIntegration:
    def __init__(self, source_code_repo, tests, artifact_name):
        self.source_code_repo = source_code_repo
        self.tests = tests
        self.artifact_name = artifact_name

    def checkout_code(self):
        """Checkout source code from the given repository"""
        try:
            output = subprocess.check_output(['git', 'clone', self.source_code_repo, self.artifact_name])
            print(output.decode("utf-8"))
        except subprocess.CalledProcessError as e:
            print(f"Error: Failed to checkout code: {e}")

    def run_tests(self):
        """Run tests for the downloaded code"""
        os.chdir(self.artifact_name)
        try:
            output = subprocess.check_output(['python', '-m', 'unittest', 'discover'])
            print(output.decode("utf-8"))
        except subprocess.CalledProcessError as e:
            print(f"Error: Failed to run tests: {e}")

    def create_artifact(self, folder, artifact_name):
        """Create artifact from the given folder"""
        try:
            with zipfile.ZipFile(f"{artifact_name}.zip", 'w') as zip_ref:
                for folder_name, subfolders, files in os.walk(folder):
                    for file in files:
                        file_path = os.path.join(folder_name, file)
                        arcname = os.path.relpath(file_path, folder)
                        zip_ref.write(file_path, arcname)
            print("Artifact created successfully")
        except Exception as e:
            print(f"Error: Failed to create artifact: {e}")

    def publish_artifact(self):
        """Publish the artifact"""
        self.create_artifact(self.artifact_name, self.artifact_name)
        print("Artifact published successfully")

    def start_ci(self):
        """Start the continuous integration process"""
        self.checkout_code()
        self.run_tests()
        self.publish_artifact()


if __name__ == "__main__":
    ci = ContinuousIntegration('https://github.com/user/repo.git', 'test','my_project')
    ci.start_ci()
