        'expires': expires_timestamp,
        'private': private
    }

    metadata_path = f'/var/www/metadata/{paste_id}.json'
    with open(metadata_path, 'w') as f:
        json.dump(metadata, f)

    return {'paste_id': paste_id, 'url': f'http://pastebin.local/{paste_id}'}

def get_paste(paste_id):
    paste_path = os.path.join('/var/www/pastebin', paste_id)

    if not os.path.exists(paste_path):
        return None

    with open(paste_path, 'r') as f:
