            print(f"Error scanning directory: {e}")

    def process_order(self, file):
        try:
            with open(file, 'r') as f:
                order_contents = f.read()
                if 'process' in order_contents:
                    print(f"Processing order {file.name}...")
                    sh.mkdir('-p', '/path/to/order/output/folder')
                    sh.cp('-p', file, f'/path/to/order/output/folder/{file.name}')
                else:
                    print(f"Skipping order {file.name}... Not a valid order")
            os.remove(file)
        except Exception as e:
            print(f"Error processing order {file.name}: {e}")

def schedule_order_processing(order_dir, minutes):
    try:
        processor = OrderProcessor(order_dir, 'username', 'group')
        files = list(processor.scan_for_orders())
        for file in files:
            processor.process_order(file)
        schedule.every(minutes).minutes.do(schedule_order_processing, order_dir, minutes)
        while True:
            schedule.run_pending()
            time.sleep(1)
