import os
import argparse

class RecursiveFileBackup:
    def __init__(self, source, destination, exclude):
        self.source = source
        self.destination = destination
        self.exclude = exclude if exclude else []

    def sync(self):
        self._handle_parent(self.source, self.destination)

    def _handle_parent(self, source, destination):
        if os.path.exists(source):
            if os.path.isfile(source):
                self._copy_if_newer(source, destination)
            elif os.path.isdir(source):
                destination_path = os.path.join(destination, os.path.basename(source))
                if not os.path.exists(destination_path):
                    os.makedirs(destination_path)
                self._update_source_to_destination(source, destination_path, self.exclude)
                [self._handle_child(source_child, destination_path) for source_child in os.listdir(source) if self._should_copy(source_child)]
        else:
            raise FileNotFoundError(f"Source path '{source}' does not exist")

    def _update_source_to_destination(self, source, destination, exclude):
        for file in os.listdir(source):
            if file in exclude or any(f.startswith(file) for f in os.listdir(source)) or os.path.basename(file) in exclude:
                continue
            source_file_path = os.path.join(source, file)
            destination_file_path = os.path.join(destination, file)
            self._copy_if_newer(source_file_path, destination_file_path)
            if os.path.isdir(source_file_path):
                self._handle_child(source_file_path, destination_file_path, exclude)

    def _handle_child(self, source, destination, exclude=None):
        exclude = exclude if exclude is not None else []
        for file in os.listdir(source):
            if os.path.join(source, file)!= destination and file not in exclude:
                child_source = os.path.join(source, file)
                self._handle_parent(child_source, destination)

    def _should_copy(self, source_file):
        source_file_path = os.path.join(self.source, source_file)
        destination_file_path = os.path.join(self.destination, source_file)
        return not os.path.exists(destination_file_path) or os.path.getmtime(source_file_path) > os.path.getmtime(destination_file_path)

    def _copy_if_newer(self, source, destination):
        if not os.path.exists(destination) or os.path.getmtime(source) > os.path.getmtime(destination):
            shutil.copy2(source, destination)
            os.utime(destination, None)

def sync_using_recursive_backup(source, destination, exclude=None):
    if not os.path.exists(destination):
        os.makedirs(destination, exist_ok=True)
    rs = RecursiveFileBackup(source, destination, exclude)
    rs.sync()

# Usage:
# sync_using_recursive_backup('/path/to/source', '/path/to/target', [".git", ".idea", "__pycache__"])
```

