from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

class FolderSyncEventHandler(FileSystemEventHandler):
    def __init__(self, src_dir, tgt_dir):
        self.src_dir = src_dir
        self.tgt_dir = tgt_dir
        self._watcher = Observer()
        self._watcher.schedule(self, self.src_dir, recursive=True)
        self._sync()
        self._watcher.start()

    @staticmethod
    def is_interesting_file(f):
        return not (f.endswith('.git') or f == '__pycache__')

    def on_modified(self, event):
        src_file = os.path.join(self.src_dir, event.src_path)
        dst_file = os.path.join(self.tgt_dir, os.path.relpath(event.src_path, self.src_dir))
        file_info = os.stat(src_file)
        try:
            dst_info = os.stat(dst_file)
            if file_info.st_ctime > dst_info.st_ctime or file_info.st_mtime > dst_info.st_mtime or file_info.st_size > dst_info.st_size:
                shutil.copy2(src_file, dst_file)
                self._chmod(dst_file, file_info.st_mode)
        except FileNotFoundError:
            shutil.copy2(src_file, dst_file)
            self._chmod(dst_file, file_info.st_mode)

    def _chmod(self, file_path, mode):
        os.chmod(file_path, mode)

    def _sync(self):
        for root, dirs, files in os.walk(self.src_dir):
            relpath = os.path.relpath(root, start=self.src_dir)
            tgt_path = os.path.join(self.tgt_dir, relpath)
            if not os.path.exists(tgt_path):
                os.makedirs(tgt_path, exist_ok=True)
            for file in [f for f in files if self.is_interesting_file(f)]:
                src_file = os.path.join(root, file)
                tgt_file = os.path.join(tgt_path, file)
                if not os.path.exists(tgt_file) or os.path.getmtime(src_file) > os.path.getmtime(tgt_file) or os.path.getsize(src_file) > os.path.getsize(tgt_file):
                    shutil.copy2(src_file, tgt_file)
                    self._chmod(tgt_file, os.stat(src_file).st_mode)

def syncUsingWatchdog(src_dir, tgt_dir):
    handler = FolderSyncEventHandler(src_dir, tgt_dir)
    while True:
        run = input("Press 'r' to run, 'q' to quit. Any other key to pause, 'w' to continue ")
        if 'q' == run.lower():
            handler._watcher.stop()
            exit()
        elif 'r' == run.lower():
            handler._sync()
            handler._watcher.start()
            continue
        elif 'w' == run.lower():
            handler._watcher.start()
            continue
        print("Press 'r' to run, 'q' to quit, 'w' to continue or Any key to pause.")

# Usage:
# sync_using_watchdog_threading('/path/to/source', '/path/to/target')
```

