import os
import re
import struct
import tarfile
from typing import Dict, List

class DiskImage:
    def __init__(self, file_path: str):
        self.file_path = file_path
        self.images: Dict[int, bytes] = {}
        self.current_offset = 0

    def _read_next_header(self) -> bytes:
        with open(self.file_path, 'rb') as f:
            self.current_offset = f.tell()
            header_size = 4
            header = f.read(header_size)
            if len(header) < header_size:
                raise ValueError('Invalid image file')
            signature, = struct.unpack('>I', header)
            if signature!= 0x12345678:
                raise ValueError('Invalid image signature')
            data_size, offset_size, = struct.unpack('>II', f.read(header_size))
            return f.read(offset_size + data_size)

    def _read_header(self, header: bytes) -> dict:
        offset_size, data_size = struct.unpack('>II', header[:8])
        return {'offset': offset_size, 'data_size': data_size}

    def _extract_images(self):
        self.current_offset = 0

        with open(self.file_path, 'rb') as f:
            while True:
                try:
                    header = self._read_next_header()
                    header_info = self._read_header(header)
                    start = self.current_offset
                    self.current_offset += header_info['offset'] + header_info['data_size']
                    self.images[start] = f.read(header_info['offset'])
                    print(f'Extracted image at offset: {start}')
                except Exception as e:
                    break

    def extract_disk_images(self, output_path: str):
        self._extract_images()
        for offset, data in self.images.items():
            with open(f'{output_path}/image_{offset}.img', 'wb') as f:
                f.write(data)


def main():
    if __name__ == "__main__":
        file_path = 'path_to_your_master_image_file.bin'
        output_path = 'path_to_output_directory'
        image = DiskImage(file_path)
        image.extract_disk_images(output_path)


# Usage
if __name__ == "__main__":
    main()
```

Note: The above script assumes that the disk image file has a custom binary header at the beginning of each image, where the first 4 bytes are the signature to indicate the start of the image, 
and the next 8 bytes are the offset and size of the image. The offset is the length of the header itself, and the size is the size of the data part of the image. 

Also please note that you need to replace `'path_to_your_master_image_file.bin'` and `'path_to_output_directory'` with actual path to your master image file and desired output directory.

