import os
import re

class FileRenamer:
    def __init__(self, directory_path):
        self.directory_path = directory_path

    def rename_files(self, pattern, replacement):
        """Rename files in the directory based on the provided pattern and replacement"""
        for filename in os.listdir(self.directory_path):
            if os.path.isfile(os.path.join(self.directory_path, filename)):
                new_name = re.sub(pattern, replacement, filename)
                if new_name!= filename:
                    full_old_path = os.path.join(self.directory_path, filename)
                    full_new_path = os.path.join(self.directory_path, new_name)
                    os.rename(full_old_path, full_new_path)
                    print(f"Renamed '{filename}' to '{new_name}'")

    def rename_files_recursive(self, pattern, replacement):
        """Rename files recursively in the directory tree"""
        for root, dirs, files in os.walk(self.directory_path):
            for filename in files:
                new_name = re.sub(pattern, replacement, filename)
                if new_name!= filename:
                    old_path = os.path.join(root, filename)
                    new_path = os.path.join(root, new_name)
                    os.rename(old_path, new_path)
                    print(f"Renamed '{os.path.join(root, filename)}' to '{new_name}'")

def main():
    directory_path = input("Enter the directory path: ")
    file_renamer = FileRenamer(directory_path)

