import dxf
import math

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def distance_to(self, other_point):
        return math.sqrt((self.x - other_point.x) ** 2 + (self.y - other_point.y) ** 2)

    def __sub__(self, other_point):
        return Point(self.x - other_point.x, self.y - other_point.y)


def parse_dxf_file(file_path):
    with open(file_path, 'rb') as file:
        dxf_file = dxf.readfrom(file)
        entities = dxf_file.entities
    return entities


def calculate_polygon_area(polygon):
    n = len(polygon)
    area = 0.0
    for i in range(n):
        j = (i + 1) % n
        area += polygon[i].y * polygon[j].x
        area -= polygon[j].y * polygon[i].x
    area = abs(area) / 2.0
    return area


def calculate_center_of_mass(polygon):
    n = len(polygon)
    x_sum, y_sum = 0.0, 0.0
    for point in polygon:
        x_sum += point.x
        y_sum += point.y
    return Point(x_sum / n, y_sum / n)


def main():
    file_path = 'path_to_your_dxf_file.dxf'
    entities = parse_dxf_file(file_path)

    # Filter out non-polygon entities
    polygons = []
    for entity in entities:
        if entity.dxftype() == 'POLYLINE':
            points = []
            for point in entity.points:
                points.append(Point(point[0], point[1]))
            polygons.append(points)

    for i, polygon in enumerate(polygons):
        print(f'Polygon {i+1} area: {calculate_polygon_area(polygon)}')
        center = calculate_center_of_mass(polygon)
        print(f'Center of mass: {center.x}, {center.y}')
        for j, point in enumerate(polygon):
            print(f'  Point {j+1}: {point.x}, {point.y}')
            print(f'    Distance to center: {center.distance_to(point)}')


if __name__ == '__main__':
    main()
