import yaml
from flask import Flask, request
import json
import logging
from typing import Dict, List
from dataclasses import dataclass

# Set up logging
logging.basicConfig(level=logging.INFO)

app = Flask(__name__)

@dataclass
class IndexedEntry:
    name: str
    value: str

@dataclass
class Index:
    def __init__(self):
        self.entries: Dict[str, List[IndexedEntry]] = {}

    def add(self, name: str, value: str):
        if name not in self.entries:
            self.entries[name] = []
        self.entries[name].append(IndexedEntry(name=name, value=value))

    def search(self, query: str) -> List[IndexedEntry]:
        return [entry for name in self.entries for entry in self.entries[name] if query in entry.value]

def load_index(config: Dict) -> Index:
    index = Index()
    for file in config['files']:
        with open(file, 'r') as f:
            yaml_config = yaml.safe_load(f)
            for key, value in yaml_config.items():
                index.add(key, value)
    return index

@app.route('/process', methods=['POST'])
def process():
    data = json.loads(request.form['index'])
    config = data.get('config', {})
    index = load_index(config)
    query = data.get('query')
    results = index.search(query)
    return json.dumps([entry.__dict__ for entry in results])

if __name__ == '__main__':
    app.run(debug=True)
