import os
import shutil
import stat

def copy_files_with_permissions(source, dest, permissions):
    os.makedirs(dest, exist_ok=True)

    for root, dirs, files in os.walk(source):
        for file in files:
            src_path = os.path.join(root, file)
            dst_path = src_path.replace(source, dest)
            file_permissions = OctalToPermissions(permissions.get(file, os.stat(src_path).st_mode))
            os.makedirs(os.path.dirname(dst_path), exist_ok=True)
            shutil.copy2(src_path, dst_path)
            os.chmod(dst_path, file_permissions)

def OctalToPermissions(octal):
    return stat.FileMode(int(octal, 8))

def get_permissions():
    permissions = {}
    for root, dirs, files in os.walk('.'):
        for file in files:
            filename = os.path.join(root, file)
            perms = input(f"Enter permissions for {filename} (in octal, e.g., 0644): ")
            permissions[filename.replace('./', '')] = perms
    return permissions

if __name__ == "__main__":
    source = input("Enter source directory path: ")
    dest = input("Enter destination directory path: ")
    if os.path.isdir(source) and os.path.isdir(dest):
        permissions = get_permissions()
        copy_files_with_permissions(source, dest, permissions)
    else:
        print("Invalid source or destination directories")
