class ArtifactCacher:
    def __init__(self):
        self.cache_dir = 'workspace/artifacts'

    def download_artifacts(self, url):
        filename = url.split('/')[-1]
        r = requests.get(url)

        if r.status_code == 200:
            file_path = os.path.join(self.cache_dir, filename)
            if not os.path.exists(self.cache_dir):
                os.makedirs(self.cache_dir)

            os.makedirs(self.cache_dir, exist_ok=True)

            with requests.get(url, stream=True) as r:
                with open(file_path, 'wb') as f:
                    shutil.copyfileobj(r.raw, f)

            # Check if file exists
            if os.path.isfile(file_path):
                # Check the MD5 sum of the downloaded artifact against the one specified in the URL.
                md5_hash = filename.split('.')[0].split('_')[-1]
                expected_md5_sum = hashlib.md5(open(file_path, 'rb').read()).hexdigest()
                if expected_md5_sum == md5_hash:
                    print(f"Artifact '{filename}' cached successfully.")
                else:
                    print(f"Warning: MD5 sum check failed for '{filename}'. The cached file may be corrupted.")

            else:
                print(f"Error: Unable to save artifact '{filename}'.")

    def get_cached_artifact(self, url):
        filename = url.split('/')[-1]
        file_path = os.path.join(self.cache_dir, filename)

        if os.path.exists(file_path):
            return open(file_path, 'rb').read()
        else:
            return self.download_artifacts(url)

    def cache_artifacts(self, artifacts):
        for url in artifacts:
            self.download_artifacts(url)

    def clear_cache(self):
        if os.path.exists(self.cache_dir):
            shutil.rmtree(self.cache_dir)

