class SourceControlSystem:
    def __init__(self, root_dir):
        self.root_dir = root_dir
        self.checkouts = {}
        self.files = set()

    def create_checkout(self, filename):
        if filename in self.checkouts:
            raise ValueError("Checkout already exists")

        path = os.path.join(self.root_dir, filename)
        os.makedirs(path, exist_ok=True)
        self.checkouts[filename] = path
        return filename

    def list_checkouts(self):
        return self.checkouts.keys()

    def update_file(self, filename, contents):
        if filename not in self.checkouts:
            raise ValueError("Checkout does not exist")

        path = self.checkouts[filename]
        with open(os.path.join(path, 'index.txt'), 'w') as f:
            f.write(contents)

    def get_checkout(self, filename):
        if filename not in self.checkouts:
            raise ValueError("Checkout does not exist")

        return self.checkouts[filename]

    def get_file_contents(self, filename):
        if filename not in self.checkouts:
            raise ValueError("Checkout does not exist")

        path = self.checkouts[filename]
        with open(os.path.join(path, 'index.txt'), 'r') as f:
            return f.read()

    def add_file(self, filename):
        if filename not in self.checkouts:
            raise ValueError("Checkout does not exist")

        self.files.add(filename)

    def remove_file(self, filename):
        if filename not in self.checkouts:
            raise ValueError("Checkout does not exist")

        self.files.discard(filename)

