        self.url = url
        self.data_dir = data_dir

    def fetch_data(self):
        try:
            response = requests.get(self.url)
            soup = BeautifulSoup(response.text, 'html.parser')
            links = soup.find_all('a', href=True)

            for link in links:
                href = link['href']
                if href.startswith('/'):
                    href = self.url + href

                link_response = requests.get(href)
                if link_response.status_code == 200:
                    filename = os.path.basename(href)
                    if filename.endswith('.gz'):
                        self._download_gzip_file(link_response.url, filename)
                    elif filename.endswith('.tar.gz'):
                        self._download_tar_gzip_file(link_response.url, filename)
        except requests.exceptions.RequestException as e:
            print(f"Request exception: {e}")

    def _download_gzip_file(self, url, filename):
        response = requests.get(url, stream=True)
        if response.status_code == 200:
            with open(os.path.join(self.data_dir, filename), 'wb') as f:
                for chunk in response.iter_content(chunk_size=1024):
                    f.write(chunk)
            self._uncompress_gzip_file(filename)

    def _download_tar_gzip_file(self, url, filename):
        response = requests.get(url, stream=True)
        if response.status_code == 200:
            with open(os.path.join(self.data_dir, filename), 'wb') as f:
                for chunk in response.iter_content(chunk_size=1024):
                    f.write(chunk)
            self._extract_tar_gzip_file(filename)

    def _uncompress_gzip_file(self, filename):
        with open(os.path.join(self.data_dir, filename), 'rb') as f_in, open(os.path.join(self.data_dir, filename.replace('.gz', '')), 'wb') as f_out:
            with gzip.GzipFile(fileobj=f_in) as gzip_file:
                shutil.copyfileobj(gzip_file, f_out)
        os.remove(os.path.join(self.data_dir, filename))

    def _extract_tar_gzip_file(self, filename):
        with tarfile.open(os.path.join(self.data_dir, f"{filename}"), 'r:gz') as tar:
            tar.extractall(path=self.data_dir)

    def run(self):
        self.fetch_data()
        print("Data downloaded and extracted successfully.")

def main():
    web_scraper = WebScraper('https://example.com/archive', './data')
    web_scraper.run()

if __name__ == "__main__":
    main()
