        try:
            with open(self.file_path, 'rb') as image_file:
                tags = exifread.process_file(image_file)
                exif_data = {}
                for tag in tags.keys():
                    if tag!= 'JPEGThumbnail':
                        exif_data[tag] = tags[tag].printable
                return exif_data
        except FileNotFoundError:
            print("File not found.")
            return None

    def extract_image_metadata(self):
        try:
            image = Image.open(self.file_path)
            exif_data = image._getexif()
            return {v: k for k, v in exif_data.items()}
        except FileNotFoundError:
            print("File not found.")
            return None

    def extract_pdf_metadata(self):
        try:
            pdf_file_obj = open(self.file_path, 'rb')
            pdf_reader = PyPDF2.PdfFileReader(pdf_file_obj)
            metadata = pdf_reader.getDocumentInfo()
            metadata_dict = {
                'Title': metadata['/Title'],
                'Author': metadata['/Author'],
                'Creator': metadata['/Creator'],
                'Producer': metadata['/Producer'],
                'Subject': metadata['/Subject'],
                'Keywords': metadata['/Keywords']
            }
            pdf_file_obj.close()
            return metadata_dict
        except FileNotFoundError:
            print("File not found.")
            return None

def main():
    file_path = 'path_to_your_file.jpg'
    analyzer = MetadataAnalyzer(file_path)

    if os.path.splitext(file_path)[1].lower() in ['.jpg', '.jpeg', '.png']:
        exif_data = analyzer.extract_exif_metadata()
        print("EXIF Data:")
