        print("PDF Metadata:")
        for key, value in pdf_metadata.items():
            print(f"{key}: {value}")
    else:
        image_metadata = analyzer.extract_image_metadata()
        if image_metadata is not None:
            print("Image Metadata:")
            for key, value in image_metadata.items():
                print(f"{key}: {value}")

if __name__ == "__main__":
