import os
import subprocess

class FfmpegWrapper:
    def __init__(self, target_dir, input_formats=['.mp4'], output_format='-h264.mp4'):
        self.target_dir = target_dir
        self.input_formats = input_formats
        self.output_format = output_format

    def get_video_list(self):
        video_files = []
        for root, dirs, files in os.walk(self.target_dir):
            for f in files:
                if any(f.endswith(ext) for ext in self.input_formats):
                    video_files.append(os.path.join(root, f))
        return video_files

    def convert_videos(self):
        videos_to_convert = self.get_video_list()
        for video in videos_to_convert:
            output = video.replace(os.path.basename(video), os.path.basename(video) + self.output_format)
            ffmpeg_cmd = ['ffmpeg', '-i', video, '-c:v', 'libx264', '-crf', '23', '-c:a', 'copy', output]
            subprocess.run(ffmpeg_cmd)

def main():
    if __name__ == '__main__':
        wrapper = FfmpegWrapper('videos')
        wrapper.convert_videos()

if __name__ == '__main__':
